window.SHELF={"id": "im", "name": "Internal Medicine", "title": "IM Shelf Video Desk", "byline": "Dr High Yield \u00b7 Emma Holliday \u00b7 Divine Intervention", "hint": "Search a topic: DKA, hyponatremia, AFib, gout\u2026", "order": ["e", "h", "d1", "d2", "d3", "d4"], "pdfs": [{"id": "divine29", "short": "Divine Ep 29", "title": "Divine Intervention Episode 29 PDF", "file": "Divine%20Intervention%20Ep29.pdf", "pages": 54, "desc": "Medicine shelf review, session 1."}, {"id": "divine30", "short": "Divine Ep 30", "title": "Divine Intervention Episode 30 PDF", "file": "Divine%20Intervention%20Ep30.pdf", "pages": 142, "desc": "Keywords A, items 1 to 137 (session 2 covers about 51 onward)."}, {"id": "divine31", "short": "Divine Ep 31", "title": "Divine Intervention Episode 31 PDF", "file": "Divine%20Intervention%20Ep31.pdf", "pages": 142, "desc": "Keywords B."}, {"id": "divine32", "short": "Divine Ep 32", "title": "Divine Intervention Episode 32 PDF", "file": "Divine%20Intervention%20Ep32.pdf", "pages": 67, "desc": "Keywords C."}]};
window.VIDS=[{"key": "h", "id": "8DTYbxtV7Tk", "who": "Dr High Yield", "title": "High Yield Internal Medicine Review", "len": 11559, "approx": false, "label": "H", "c": "h1", "short": "Dr High Yield", "rail": "Dr High Yield", "sections": [{"t": 55, "title": "Scores and criteria", "notes": ["CHA2DS2-VASc for AFib: CHF, HTN, **age 75+ (2)**, diabetes, **stroke (2)**, vascular disease, age 65 to 74, female. Score 2+ = anticoagulate.", "Centor (strep): no cough, exudates, anterior nodes, fever, age adjust. **4+ treat**, 2 to 3 rapid strep.", "POUND for migraine. CURB-65: **2+ admit**.", "SIRS: 2+ of RR, temp, WBC (over 12 or under 4), HR. With infection = sepsis."]}, {"t": 258, "title": "Light criteria, Wells, oxygen, GCS", "notes": ["Exudate if fluid/serum protein **over 0.5** or LDH **over 0.6**. Exudate = pneumonia, cancer. Transudate = CHF, cirrhosis, nephrotic.", "Wells PE: **4+ CT angiogram**, under 4 D-dimer.", "Home oxygen in COPD: **SpO2 under 88%** or PaO2 under 55.", "GCS **8 or less = intubate**."]}, {"t": 396, "title": "Ascites, SAAG, TIMI", "notes": ["Ascitic fluid **250+ neutrophils = SBP**.", "SAAG (serum minus ascites) **over 1.1 = portal hypertension**.", "TIMI 0 to 2 = stress test, **3+ = cath lab** (unstable angina or NSTEMI)."]}, {"t": 482, "title": "Stable angina and stress testing", "notes": ["Exertional chest pain relieved by rest. Next step: **stress test**.", "Abnormal baseline ECG: stress echo or nuclear. Cannot exercise: **pharmacologic** (adenosine, dipyridamole, dobutamine).", "Definitive diagnosis: **angiography**. Treatment: nitrates, aspirin, beta blocker."]}, {"t": 657, "title": "Acute coronary syndrome", "notes": ["ECG first. **STEMI** (1 mm in 2 contiguous leads or new LBBB) = cath lab, no need to wait for troponin.", "No ST elevation: serial troponin. Rises = **NSTEMI**, stays normal = unstable angina.", "MONA plus clopidogrel, beta blocker, ACE inhibitor, statin, heparin. **Aspirin first**."]}, {"t": 862, "title": "CABG, Prinzmetal, inferior MI", "notes": ["CABG: **3-vessel or proximal LAD** disease.", "Prinzmetal: vasospasm, transient ST elevation. **Calcium channel blocker** or nitrates.", "Inferior MI (II, III, aVF, RV involvement): **no nitrates, give fluids**. Bradycardia from SA node injury: **atropine**.", "Only 3 drugs lower MI mortality: **aspirin, beta blocker, ACE inhibitor**."]}, {"t": 1007, "title": "Heart block, Dressler, restrictive cardiomyopathy", "notes": ["Mobitz I: no treatment. **Mobitz II and complete block: pacemaker**.", "Dressler: pericarditis **2 weeks after MI**, treat with **aspirin**.", "Restrictive cardiomyopathy: **hemochromatosis, amyloidosis, sarcoidosis**."]}, {"t": 1119, "title": "CHF drugs, metformin, acute decompensation", "notes": ["CHF mortality benefit: **ACE inhibitor, beta blocker, spironolactone**.", "Metformin: avoid in **renal failure and decompensated CHF** (lactic acidosis).", "Acute decompensated CHF: LMNOP. **Loop diuretic first**."]}, {"t": 1176, "title": "Arrhythmias", "notes": ["Narrow-complex SVT: **vagal maneuvers, then adenosine**. Unstable: cardioversion.", "VT: amiodarone, unstable = cardioversion. **VFib and pulseless VT: defibrillate**.", "PEA and asystole: CPR, no shock. **Torsades: IV magnesium**."]}, {"t": 1273, "title": "Pericardial disease and tamponade", "notes": ["Constrictive pericarditis: **calcified pericardium** on x-ray, TB. Pericardiectomy.", "Acute pericarditis: Coxsackie, **diffuse ST elevation**, better leaning forward. NSAIDs.", "Tamponade: **Beck triad** (hypotension, JVD, muffled sounds), **pulsus paradoxus**, electrical alternans."]}, {"t": 1410, "title": "Mitral and aortic stenosis", "notes": ["Mitral stenosis: **rheumatic heart disease**.", "Aortic stenosis: **angina, syncope, CHF**, soft S2. Valve area under 1 cm2 or any symptom = replace valve."]}, {"t": 1497, "title": "Tricuspid valve, holosystolic murmurs, endocarditis", "notes": ["Tricuspid disease: **IV drug use and carcinoid** (flushing, diarrhea, bronchospasm).", "Holosystolic: **MR, TR, VSD**.", "Endocarditis: fever + new murmur. **Blood cultures first**, empiric **vancomycin + aminoglycoside**."]}, {"t": 1556, "title": "Hypertensive emergency vs urgency", "notes": ["Over 180/120. **End-organ damage = emergency**: IV labetalol, nitroprusside, hydralazine.", "No end-organ damage = urgency: **oral** meds."]}, {"t": 1601, "title": "Subarachnoid hemorrhage and aortic dissection", "notes": ["Thunderclap headache: **CT head without contrast**, negative = LP for **xanthochromia**.", "Dissection: tearing pain to the back. CT angiogram or TEE. **Type A = surgery, type B = beta blocker**.", "Check kidneys before contrast CT."]}, {"t": 1676, "title": "Peripheral artery disease and Leriche", "notes": ["Smoking is the top risk. **ABI under 0.9** = disease, under 0.4 = severe, rest pain.", "Claudication: **exercise program first**. Rest pain: stent or bypass.", "Acute limb ischemia (cold, pulseless): **heparin, embolectomy**.", "Leriche: aortoiliac disease, **buttock claudication + impotence**."]}, {"t": 1815, "title": "PE, IVC filter, shock types", "notes": ["Suspected PE: **heparin before CT angiogram**.", "IVC filter: contraindication to or failure of anticoagulation. LMWH avoided in renal failure.", "Venous ulcer: **medial malleolus**.", "Cardiogenic shock: **dobutamine**. Septic: antibiotics + fluids + pressors. Neurogenic: everything low, **fluids**."]}, {"t": 1910, "title": "COPD", "notes": ["Chronic bronchitis vs emphysema. Hyperresonance, decreased breath sounds.", "Only 2 things lower mortality: **quitting smoking and home oxygen**.", "Home oxygen: **PaO2 under 55 or SpO2 under 88%**.", "Exacerbation (sputum change): **steroids + antibiotic + BiPAP**, target 88 to 92%. COPD with pneumonia: think **Pseudomonas** (piperacillin-tazobactam, cefepime)."]}, {"t": 2090, "title": "Asthma, bronchiectasis, cystic fibrosis", "notes": ["Asthma attack with **normal or high PCO2 = tiring out, intubate**.", "Step up from SABA to low, medium, high-dose inhaled steroid.", "Bronchiectasis: buckets of sputum, **high-resolution CT**.", "CF: **Staph aureus under 20, Pseudomonas over 20**. Pancreatic enzymes, ADEK, dornase."]}, {"t": 2263, "title": "Lung cancer and Pancoast tumour", "notes": ["Pancoast: **Horner, SVC syndrome**, brachial plexus, phrenic and recurrent laryngeal nerve.", "Central in smokers: **squamous = PTHrP, hypercalcemia**. **Small cell = SIADH, ACTH, Lambert-Eaton** (improves with use).", "Adenocarcinoma: non-smokers, peripheral.", "New nodule: **compare with an old x-ray first**, then CT."]}, {"t": 2403, "title": "Pneumothorax", "notes": ["Decreased breath sounds, hyperresonance, decreased fremitus.", "Tension: **tracheal deviation + hypotension**. **Needle decompression first**, then chest tube."]}, {"t": 2461, "title": "Interstitial lung disease and sarcoidosis", "notes": ["Asbestosis: **pleural plaques**, mesothelioma. Silicosis: **eggshell calcification**, upper lobes.", "Upper lobes: silicosis, TB, Aspergillus.", "Sarcoidosis: **bilateral hilar nodes, high calcium, high ACE**. Steroids."]}, {"t": 2550, "title": "Respiratory failure and ventilator settings", "notes": ["High PCO2 = hypoventilation (COPD, obesity). Low PO2 = lung disease.", "**Tidal volume and rate fix PCO2**. **FiO2 and PEEP fix PaO2**.", "ARDS: **high PEEP, low tidal volume**. Pulmonary hypertension: mean PA pressure **over 25**."]}, {"t": 2723, "title": "Aspiration pneumonia and PCP", "notes": ["Aspiration: dementia, seizures, alcohol, stroke. **Right lower lobe**, cover anaerobes (**clindamycin**).", "PCP: bilateral interstitial infiltrates. **TMP-SMX** prophylaxis when **CD4 under 200**.", "Add **steroids if PaO2 under 70** or A-a gradient over 35."]}, {"t": 2797, "title": "GI: colon cancer, diverticula, mesenteric ischemia", "notes": ["After any cancer diagnosis: **stage with CT**.", "Diverticulitis: **CT with contrast**. Diverticulosis bleed: painless, lots of blood.", "Mesenteric ischemia: **pain out of proportion to exam**, AFib, atherosclerosis. Angiography."]}, {"t": 2884, "title": "Ogilvie, ileus, volvulus, varices, SBP", "notes": ["Ogilvie: colon only dilated, elderly post-op. Ileus: small and large bowel, **decreased bowel sounds**.", "Sigmoid volvulus: **coffee bean sign**, sigmoidoscopy to detorse.", "Varices: **octreotide** acute, **beta blocker** prophylaxis.", "SBP: fever + abdominal pain in cirrhosis. **Over 250 neutrophils**, ceftriaxone."]}, {"t": 2992, "title": "Liver masses and abscesses", "notes": ["Young woman on the pill + liver mass = **hepatic adenoma**. Resect if over 5 cm.", "Hydatid cyst (Echinococcus, dogs): **cysts within a cyst**. Albendazole + resection.", "Pyogenic abscess: after cholangitis, E coli. **Drainage + antibiotics**.", "Amebic abscess: **fever, RUQ pain, diarrhea**, eosinophilia. **Metronidazole**."]}, {"t": 3120, "title": "Unconjugated and conjugated hyperbilirubinemia", "notes": ["Jaundice **at birth = pathologic**, next step Coombs.", "Crigler-Najjar: no UGT. **Gilbert: mild, appears with illness or fasting**.", "Dubin-Johnson: **black liver**. Rotor: same but normal liver.", "Raised AST/ALT: autoimmune, hep B and C, drugs, ethanol, fatty liver, tumour, shock liver, iron."]}, {"t": 3236, "title": "Cholecystitis and HIDA scan", "notes": ["Suspected cholecystitis: **RUQ ultrasound first**. Equivocal ultrasound: **HIDA scan** (gallbladder does not fill).", "Ultrasound: wall over 4 mm, pericholecystic fluid, stones."]}, {"t": 3291, "title": "Choledocholithiasis and cholangitis", "notes": ["**Charcot triad**: RUQ pain, fever, jaundice. **Reynolds pentad** adds confusion + hypotension.", "Treat: fluids, IV antibiotics, **ERCP**. Untreated: pyogenic liver abscess."]}, {"t": 3385, "title": "Gallstone pancreatitis and ileus", "notes": ["Pancreatitis confirmed by lipase: next imaging is **RUQ ultrasound** (look for stones), not CT.", "Gallstone pancreatitis: **cholecystectomy in the same admission**.", "Gallstone ileus: **air in the biliary tree** + small bowel obstruction at the terminal ileum."]}, {"t": 3496, "title": "Acalculous cholecystitis, PSC, PBC", "notes": ["ICU patient on TPN: **acalculous cholecystitis**. Treat: **percutaneous cholecystostomy**.", "PSC: **beaded bile ducts, ulcerative colitis**.", "PBC: **anti-mitochondrial antibody**, severe itch, middle-aged woman. **Ursodiol**."]}, {"t": 3617, "title": "Appendicitis and carcinoid", "notes": ["Classic picture = **appendectomy** without imaging. Equivocal = CT.", "Carcinoid: serotonin steals tryptophan = **niacin deficiency** (diarrhea, dermatitis, dementia). Flushing, bronchospasm, right heart lesions."]}, {"t": 3731, "title": "Pancreatic pseudocyst, chronic pancreatitis, aortoenteric fistula", "notes": ["Pseudocyst: **2 to 3 weeks after pancreatitis**, early satiety. Observe, drain if large or symptomatic.", "Chronic pancreatitis: **calcifications**.", "Aortoenteric fistula: **GI bleed after aortic graft surgery**."]}, {"t": 3814, "title": "Dysphagia, achalasia, Zenker", "notes": ["Any dysphagia: **barium swallow first**, unless alarm features (age 55+, weight loss) = endoscopy.", "Achalasia: LES **fails to relax**, bird beak.", "Zenker: elderly, food sticks in the throat, **halitosis**."]}, {"t": 3895, "title": "Peptic ulcer, H pylori, dyspepsia", "notes": ["Ulcers: **H pylori or NSAIDs**.", "Young, no alarm features: **PPI trial**. From a high-prevalence area: **test for H pylori** (breath or stool antigen).", "**Alarm features (age 55+, weight loss, anemia): endoscopy**."]}, {"t": 3980, "title": "Colon cancer screening and IBD", "notes": ["Iron deficiency in anyone **over 50 = colon cancer until proven otherwise**, colonoscopy.", "Screening from 50 every 10 years. **First-degree relative: at 40 or 10 years before their diagnosis**.", "Crohn: skip lesions, transmural, mouth ulcers, fistulas. UC: **always rectum, continuous, PSC**.", "Pyoderma gangrenosum: sterile ulcer of IBD, **steroids not antibiotics**."]}, {"t": 4106, "title": "Thyroid nodule work-up", "notes": ["New nodule: **TSH + ultrasound**.", "Low TSH (hot): **radioactive iodine uptake**. Diffuse = Graves, one area = toxic adenoma, patchy = toxic multinodular goitre.", "Normal TSH: **FNA if over 1 cm**."]}, {"t": 4188, "title": "Hyperthyroid with low uptake, TBG", "notes": ["**No uptake = leaking gland**: postpartum, subacute (de Quervain), Hashimoto early phase, or exogenous.", "Pregnancy or the pill raise TBG: hypothyroid patients **need a higher levothyroxine dose**."]}, {"t": 4348, "title": "Hashimoto, de Quervain, medullary cancer", "notes": ["Hashimoto: other autoimmune disease, **risk of thyroid lymphoma**.", "De Quervain: **painful** thyroid after a URI, low uptake. NSAIDs.", "Medullary: calcitonin, MEN 2A and 2B. **Check urine metanephrines before surgery** to rule out pheochromocytoma."]}, {"t": 4576, "title": "Acromegaly, SIADH, Cushing, adrenal insufficiency", "notes": ["Acromegaly: **IGF-1 first**.", "SIADH: **fluid restriction** first.", "Cushing screen: **overnight dexamethasone**, 24-hour urine cortisol, late-night salivary cortisol.", "Adrenal insufficiency: ACTH stimulation. Addison is usually autoimmune."]}, {"t": 4697, "title": "Hyperaldosteronism and renal artery stenosis", "notes": ["HTN + high sodium + **low potassium**: **renin to aldosterone ratio** first.", "High aldosterone, low renin = **Conn** (adrenal). Both high = **renal artery stenosis** or fibromuscular dysplasia.", "RAS: older, suddenly **refractory HTN**, abdominal bruit. FMD: **young woman**, bruit."]}, {"t": 4907, "title": "Diabetes diagnosis and metformin", "notes": ["Diagnosis: **fasting 126+ twice**, random 200+ with symptoms, or **A1c 6.5%+**.", "Metformin first line. Avoid in **renal failure and CHF** (lactic acidosis).", "Top cause of death in diabetes and RA: **MI**."]}, {"t": 5000, "title": "DKA vs HHS", "notes": ["DKA: **anion gap acidosis**, glucose 300 to 500, Kussmaul breathing.", "HHS: **glucose near 1000**, no acidosis.", "Treat: **IV fluids + insulin infusion**. Add potassium when it falls, total body potassium is low.", "**Stop the insulin drip when the gap closes**."]}, {"t": 5116, "title": "Zollinger-Ellison and glucagonoma", "notes": ["ZE: multiple ulcers + diarrhea. Gastrin over 1000, **secretin fails to suppress**. PPI or surgery.", "Glucagonoma: hyperglycemia + **necrolytic migratory erythema**.", "Beta blocker overdose antidote: **glucagon**."]}, {"t": 5173, "title": "Rheumatoid arthritis vs lupus", "notes": ["Fetus with congenital heart block: **neonatal lupus** (anti-Ro).", "RA: symmetric MCP and PIP, **morning stiffness**, spares DIP. **Anti-CCP**. NSAIDs, **methotrexate**, steroids for flares.", "Lupus (SOAP BRAIN MD): 4 of 11. **Anti-dsDNA, anti-Smith**. NSAIDs, **hydroxychloroquine**, steroids for flares."]}, {"t": 5322, "title": "Antiphospholipid syndrome", "notes": ["**Recurrent miscarriages + clots**.", "Prolonged PTT **not corrected by mixing**, false-positive VDRL."]}, {"t": 5353, "title": "Gout vs pseudogout", "notes": ["Gout: sudden painful **big toe**, wakes them up. **Tap the joint**: negatively birefringent needles.", "Pseudogout: **positively birefringent rhomboids**, chondrocalcinosis.", "Acute gout: NSAIDs or colchicine. **CKD: intra-articular steroids**."]}, {"t": 5434, "title": "Polymyositis vs polymyalgia vs fibromyalgia", "notes": ["Polymyositis = **weakness**, high CK. Dermatomyositis: Gottron papules, heliotrope rash, **look for cancer**.", "PMR = **stiffness** of hips and shoulders, elderly, **high ESR, normal CK**. Low-dose steroids.", "Giant cell arteritis: **high-dose steroids now**, risk of blindness. Biopsy.", "Fibromyalgia = **pain at tender points**. TCA or SNRI.", "Sudden psoriasis or molluscum in an adult: **test for HIV**."]}, {"t": 5608, "title": "Uremia and dialysis indications", "notes": ["WBC casts: **interstitial nephritis or pyelonephritis**.", "Uremia: pericarditis, platelet dysfunction, confusion with asterixis. **All need dialysis**.", "AEIOU: refractory acidosis, electrolytes (K), intoxication (methanol, aspirin, lithium, ethylene glycol), overload, uremia.", "CKD: **hypertension and diabetes**."]}, {"t": 5760, "title": "Interstitial nephritis vs ATN", "notes": ["AIN: **NSAIDs, diuretics, antibiotics**. Fever, eosinophilia, rash, **WBC casts**. Stop the drug.", "ATN: shock or toxins, **muddy brown casts**.", "Pre-renal: **BUN to creatinine over 20**."]}, {"t": 5868, "title": "Metabolic acidosis and RTA", "notes": ["Anion gap: MUDPILES. Non-gap: **diarrhea or RTA**.", "Type 1: cannot excrete H, **kidney stones**. Type 2: **bicarb wasting**. Type 4: **low aldosterone, high potassium**.", "Metabolic alkalosis: **urine chloride**. Low = vomiting, high = kidney cause."]}, {"t": 6091, "title": "Calcium oxalate stones", "notes": ["Fat malabsorption binds calcium, frees oxalate = **oxalate stones**.", "Prevention: **normal to high calcium**, low salt, low fat, lots of water."]}, {"t": 6209, "title": "Hematuria, testicular mass", "notes": ["Old smoker, painless gross hematuria: flank mass = **renal cell (CT)**, otherwise **bladder cancer (cystoscopy)**.", "Testicular mass: **scrotal ultrasound**, then **inguinal orchiectomy**, never biopsy through the scrotum."]}, {"t": 6291, "title": "Torsion vs epididymitis", "notes": ["Torsion: sudden pain, **absent cremasteric reflex**, worse with elevation. Clear case = **surgery, fix both sides**. Unclear = Doppler.", "Epididymitis: **fever, pain relieved by elevation**, reflex present.", "Under 35: **gonorrhea and chlamydia** (ceftriaxone + azithromycin). Over 35: **E coli** (fluoroquinolone)."]}, {"t": 6500, "title": "Hyponatremia work-up", "notes": ["Step 1: **serum osmolality**. High = glucose. Normal = pseudohyponatremia (lipids, protein). Low = go on.", "Step 2: **volume status**. Hyper: CHF, cirrhosis, nephrotic. Eu: **SIADH, primary polydipsia**. Hypo: diarrhea, vomiting, diuretics.", "Step 3: **urine sodium over 20** = renal loss (diuretics, SIADH, kidney injury). Under 20 = extrarenal."]}, {"t": 6748, "title": "Treating hyponatremia and hypernatremia", "notes": ["Hyper or euvolemic, no symptoms: **fluid restriction**. Hypovolemic: **normal saline**.", "Severe (under 120) or symptomatic (confusion, seizure): **3% saline**.", "Hypernatremia: correct slowly, **\"high to low, brains blow\"**. Free water if eu or hypervolemic, 1/2 NS if dry, NS if dry and symptomatic."]}, {"t": 6980, "title": "Calcium, potassium, magnesium", "notes": ["Massive transfusion: **citrate binds calcium**, hypocalcemia.", "Hypercalcemia: **IV fluids first**.", "Hyperkalemia with ECG changes: **calcium gluconate first**, then insulin + glucose, binder.", "Hypermagnesemia: **loss of reflexes** first. Calcium gluconate."]}, {"t": 7067, "title": "PTH axis patterns", "notes": ["Primary hyperparathyroidism: **high PTH, high calcium, low phosphate**. Parathyroidectomy.", "Kidney failure: **high PTH, low calcium, high phosphate**.", "Vitamin D deficiency: **low calcium, low phosphate, high PTH**.", "Squamous lung cancer PTHrP: **high calcium, low phosphate, low PTH**."]}, {"t": 7380, "title": "Ventilator and acid-base steps", "notes": ["PCO2 high: raise **tidal volume or rate**. PaO2 low: raise **FiO2 or PEEP**.", "Check pH, then CO2 and bicarb. Low pH + low bicarb = metabolic acidosis: **calculate the anion gap**.", "Non-gap: **urine anion gap** negative = GI loss, positive = RTA.", "Metabolic alkalosis: **urine chloride**."]}, {"t": 7682, "title": "Anemia: retic, MCV, B12 vs folate", "notes": ["High **reticulocytes = hemolysis** or bleeding.", "Microcytic: iron, chronic disease, sideroblastic, thalassemia (FAST).", "B12 vs folate: B12 has **neuro signs and high methylmalonic acid**. Hypersegmented neutrophils.", "Fanconi: **absent thumb + pancytopenia**. Diamond-Blackfan: triphalangeal thumb, anemia only."]}, {"t": 7827, "title": "Transfusion reactions by timing", "notes": ["**Seconds: anaphylaxis**, IgA deficiency, wash the blood.", "**Minutes: ABO hemolysis**, hypotension, flank pain. IV fluids.", "**Hours: febrile** non-hemolytic, cytokines. Leukoreduce.", "**Days: delayed hemolysis**, jaundice, self-limited."]}, {"t": 7889, "title": "Microcytic anemias and iron studies", "notes": ["High RDW + microcytic = **iron deficiency**. Thalassemia: normal RDW.", "High MCHC = **hereditary spherocytosis**, splenectomy.", "Beta thalassemia: Mediterranean, **crew-cut skull, high HbA2**. Alpha: Asian.", "Sideroblastic: **B6 deficiency, lead, isoniazid**. Hemochromatosis: bronze diabetes, high LFTs, **phlebotomy**.", "Chronic disease: **high ferritin, low iron, low TIBC**. Treat the underlying disease."]}, {"t": 8163, "title": "Aplastic crisis, spherocytes, AIHA", "notes": ["Aplastic crisis = red cells only, **parvovirus B19**. In pregnancy: **hydrops fetalis**.", "Spherocytes: hereditary spherocytosis or **autoimmune hemolysis**.", "Warm (IgG): **lymphoma, CLL, lupus**, splenomegaly, **steroids**. Cold (IgM): **Mycoplasma, mono**, avoid cold."]}, {"t": 8311, "title": "TTP", "notes": ["**ADAMTS13 deficiency** = excess von Willebrand factor, platelet clumps, schistocytes.", "Fever, anemia, low platelets, renal failure, neuro signs (FAT RN)."]}, {"t": 8413, "title": "HUS and HIT", "notes": ["HUS: **EHEC from undercooked beef**. Anemia, low platelets, renal failure.", "HIT: platelets fall **over 50% about day 5 to 10** of heparin. **Stop all heparin, start argatroban**. Prothrombotic."]}, {"t": 8528, "title": "von Willebrand disease and DIC", "notes": ["vWD: mucosal bleeding, heavy periods. **High bleeding time and PTT**, low ristocetin activity. **Desmopressin**.", "DIC: low platelets, schistocytes, **high PT and PTT, low fibrinogen**, oozing from lines."]}, {"t": 8713, "title": "Oncologic emergencies and lymphoma", "notes": ["Hypercalcemia: fluids. Cord compression: **steroids**. Tamponade: pericardiocentesis. Tumour lysis: fluids.", "Hodgkin: **Reed-Sternberg**, contiguous nodes. Non-Hodgkin: scattered nodes.", "Node 1 cm+, painless, over a month, no infection: **excisional biopsy**."]}, {"t": 8797, "title": "Leukemias and polycythemia", "notes": ["Acute: **20%+ blasts**. AML: Auer rods.", "CML: very high WBC, **high basophils**, low LAP score. **Imatinib**.", "Polycythemia: check **EPO**. Low = polycythemia vera (**itch after hot shower**). High = secondary (hypoxia, sleep apnea)."]}, {"t": 8983, "title": "Pneumonia bugs and antibiotics", "notes": ["Typical: S pneumoniae, H flu, Moraxella. Atypical: Mycoplasma, Chlamydia, Legionella. Hospital: E coli, **Pseudomonas, S aureus**.", "Outpatient: **amoxicillin** (typical) or **azithromycin** (atypical). Inpatient: **fluoroquinolone**.", "Aspiration: clindamycin. Hospital-acquired: **piperacillin-tazobactam or cefepime**."]}, {"t": 9078, "title": "Tuberculosis", "notes": ["PPD positive: **5 mm** HIV or close contact, **10 mm** health workers, prison, immigrants, **15 mm** everyone else.", "Positive PPD: **chest x-ray** (BCG history does not matter).", "Active TB: **RIPE 2 months, then RI 4 months**. Give **B6 with isoniazid**.", "Latent: isoniazid 9 months. Stop drugs only if LFTs over 3 times normal.", "Pyrazinamide = gout. Ethambutol = **eyes**. Rifampin = orange fluids."]}, {"t": 9225, "title": "Meningitis", "notes": ["Under 3 months: **GBS, E coli, Listeria**. Others: S pneumoniae, H flu, N meningitidis (rash).", "Empiric: **vancomycin + ceftriaxone**. Add **ampicillin over 50 or immunocompromised**.", "CSF: bacterial = **neutrophils, low glucose**. Viral = lymphocytes, normal glucose. Fungal and TB = lymphocytes, low glucose.", "Cryptococcus: **India ink**, amphotericin. HSV: **temporal lobes**, seizures, red cells in CSF."]}, {"t": 9406, "title": "UTI and STIs", "notes": ["Uncomplicated UTI: TMP-SMX, nitrofurantoin, fluoroquinolone. Pregnant: nitrofurantoin, amoxicillin, cephalosporin.", "Culture if: **diabetic, pregnant, male, immunosuppressed**.", "Over 2 UTIs a year: **TMP-SMX prophylaxis** (daily or after sex)."]}, {"t": 9493, "title": "HIV", "notes": ["Cesarean if **viral load over 1000**. No breastfeeding.", "Acute HIV: mono-like + **rash**.", "Prophylaxis: **CD4 under 200 TMP-SMX** (PCP), under 50 azithromycin (MAC).", "Diarrhea: **Cryptosporidium watery, CMV bloody, MAC fever**. Cryptococcus: pigeons, amphotericin."]}, {"t": 9584, "title": "Genital ulcers and syphilis", "notes": ["**Painless**: syphilis, LGV (painful buboes), granuloma inguinale (ulcerating nodes).", "**Painful**: HSV and chancroid.", "Syphilis: chancre, then palms and soles rash + condyloma lata, then gummas, **tabes dorsalis**, aortitis."]}, {"t": 9640, "title": "Skin infections and necrotizing fasciitis", "notes": ["Cellulitis and erysipelas: **Strep pyogenes**. Erysipelas is fast with **sharp borders**.", "Abscess: **S aureus**.", "Necrotizing fasciitis: **pain out of proportion**. Gas = Clostridium perfringens."]}, {"t": 9697, "title": "Tetanus prophylaxis", "notes": ["3+ doses, clean wound: booster if **over 10 years**. Dirty wound: if **over 5 years**.", "Under 3 doses or unknown: vaccine for any wound, **plus immunoglobulin if dirty**."]}, {"t": 9762, "title": "Septic arthritis, osteomyelitis, Lyme", "notes": ["Bugs: **S aureus**, sickle cell = **Salmonella**, IV drugs = **Pseudomonas**.", "Hot swollen joint: **arthrocentesis**, over 50,000 WBC = septic.", "Lyme: erythema migrans. **Doxycycline over 8, amoxicillin under 8**."]}, {"t": 9855, "title": "Malaria, rabies, cat scratch", "notes": ["Malaria: travel + cyclic fevers. Vivax and ovale: **add primaquine** for liver forms.", "Rabies (bats): wash wound + **immunoglobulin + vaccine**.", "Cat scratch: **Bartonella**, node near the scratch. Azithromycin."]}, {"t": 9941, "title": "Aspergillus and dimorphic fungi", "notes": ["ABPA: asthma + eosinophils. Aspergilloma: **fungus ball**, hemoptysis. Invasive: **halo sign**, amphotericin or voriconazole.", "Histoplasma: **bats and caves**, hilar nodes."]}, {"t": 9996, "title": "Blasto, cocci, sporothrix, parasites", "notes": ["Blastomyces: **Midwest**, skin lesions + pneumonia. Coccidioides: **Arizona, California**.", "Sporothrix: **rose thorn**, nodules up the arm. Itraconazole.", "Worms: **eosinophilia**. Pinworm: tape test, albendazole. Tapeworms: praziquantel. Schistosoma: hematuria."]}, {"t": 10134, "title": "Toxic shock and neutropenic fever", "notes": ["TSS: **tampon or nasal packing**, shock, desquamation. Fluids + vancomycin, remove source.", "Neutropenic fever (ANC under 1500): **piperacillin-tazobactam** for Pseudomonas."]}, {"t": 10191, "title": "Gastroenteritis and C difficile", "notes": ["Watery: rotavirus, norovirus, ETEC (travel). Bloody: Campylobacter, EHEC, Salmonella, Shigella, Yersinia.", "Bloody + fever: **stool WBC**, positive = culture.", "Antibiotics only if very young, old or immunosuppressed. **Never for EHEC** (HUS).", "Diarrhea after antibiotics: **C diff toxin**."]}, {"t": 10254, "title": "Acne, rosacea, seborrheic dermatitis", "notes": ["Acne: **topical benzoyl peroxide or retinoid**, then topical then oral antibiotic, then **isotretinoin**.", "Rosacea: flushing, **metronidazole**, eye involvement.", "Keratoacanthoma: grows fast, **reassure**.", "Seborrheic dermatitis: **nasolabial folds**, selenium or azoles. Linked to **HIV and Parkinson**."]}, {"t": 10335, "title": "Contact dermatitis, pityriasis rosea, SJS", "notes": ["Contact dermatitis: type IV, **topical steroids**.", "Pityriasis rosea: **herald patch**, Christmas tree. Reassure.", "Erythema multiforme: target lesions, **HSV**. SJS from sulfa, anticonvulsants, allopurinol. **Over 30% = TEN**."]}, {"t": 10397, "title": "Blistering disease, zoster, tinea, scabies", "notes": ["Pemphigus vulgaris: desmosomes, **mouth involved**. Bullous pemphigoid: hemidesmosomes, **no mouth lesions**. Steroids.", "Shingles vaccine from 50 to 60.", "Tinea capitis: **oral griseofulvin**. Other tinea: topical azole.", "Scabies: **itch worse at night**, finger webs, household. **Permethrin** for everyone."]}, {"t": 10532, "title": "Skin cancers", "notes": ["Actinic keratosis: sun-exposed scaly patch, **5-fluorouracil**, risk of squamous cell.", "Basal cell: **pearly with telangiectasias**.", "Marjolin ulcer: chronic wound turns **squamous cell**, biopsy."]}, {"t": 10616, "title": "Anaphylaxis, eye, kidney, lipids", "notes": ["Anaphylaxis: **IM epinephrine**.", "Retinal artery occlusion: **cherry-red spot**. Vein: blood and thunder.", "Proteinuria in CKD or diabetes: **ACE inhibitor**.", "Statins: **ASCVD, diabetes 40+ with LDL 70+, LDL 190+, high 10-year risk**. Fibrates if TG over 1000."]}, {"t": 10758, "title": "Headaches, rhinitis", "notes": ["Cluster: one-sided eye pain, tearing, runny nose. **100% oxygen**, verapamil to prevent.", "Tension: bilateral band. Migraine: **triptan**, prevent with beta blocker or TCA.", "Postnasal drip: antihistamine. Allergic rhinitis: **intranasal steroid**."]}, {"t": 10849, "title": "Abdomen, IBS, interstitial cystitis", "notes": ["Acute abdomen: **abdominal x-ray** to rule out free air.", "IBS: alternating bowel habits, **relieved by a bowel movement**.", "Interstitial cystitis: UTI symptoms, **clean urine**, relieved by voiding."]}, {"t": 10907, "title": "Back pain", "notes": ["Disc: **worse bending forward**. Stenosis: **worse extending**, better bending forward.", "Disc herniation: **conservative first**. MRI after 6 weeks or red flags.", "**MRI now**: cauda equina (saddle anesthesia, incontinence), epidural abscess (fever, point tenderness).", "Metastases: night pain, point tenderness."]}, {"t": 11051, "title": "Osteoarthritis, osteoporosis, glaucoma", "notes": ["OA: **obesity**, worse with use. Weight loss, analgesics.", "Osteoporosis: **DEXA at 65**, T-score -2.5. **Bisphosphonate**.", "Acute angle closure: rock-hard red eye, halos. **Pilocarpine + beta blocker**.", "Blepharitis: warm compress. Bacterial conjunctivitis: erythromycin."]}, {"t": 11179, "title": "Obesity and incontinence", "notes": ["Bariatric surgery: **BMI 40+, or 35+ with comorbidity**.", "Stress incontinence: cough or sneeze. **Kegels**, pessary, sling.", "Urge: **bladder training, oxybutynin**.", "Overflow: diabetes, spinal cord. **Intermittent catheterization**, bethanechol."]}, {"t": 11346, "title": "Addiction and screening", "notes": ["Alcohol: naltrexone, acamprosate. Smoking: **nicotine replacement**, varenicline, bupropion (avoid with seizures, eating disorders).", "Colon from 50, stop at 75. Pap 21 to 65 every 3 years. **AAA once at 65 in men who ever smoked**.", "Lung cancer: low-dose CT 55+ with **30 pack-years**, quit under 15 years ago.", "Chlamydia and gonorrhea: **women under 25**. Mild cold is not a reason to delay a vaccine."]}]}, {"key": "e", "id": "0DjHPWUc5tY", "who": "Emma Holliday", "title": "Internal Medicine Shelf Review", "len": 7170, "approx": false, "label": "E", "c": "e", "short": "Emma Holliday", "rail": "Emma Holliday", "sections": [{"t": 31, "title": "STEMI: ECG first", "notes": ["Chest pain: **ECG first**. STEMI = ST elevation or **new LBBB**.", "Later changes: T inversion, then **Q waves** (old infarct).", "**II, III, aVF = inferior, right coronary**."]}, {"t": 142, "title": "Reperfusion and thrombolytic contraindications", "notes": ["Cath lab is best. Thrombolytics if **no PCI available**, within the window.", "Contraindications: active bleeding, **any prior hemorrhagic stroke**, recent ischemic stroke, recent head trauma."]}, {"t": 223, "title": "Right ventricular infarction", "notes": ["**Shock + JVD + clear lungs**.", "**No nitrates, give fluids** (they need preload)."]}, {"t": 309, "title": "Cardiac enzymes and NSTEMI", "notes": ["Normal ECG: **serial enzymes**, at least 3 sets.", "Reinfarction days later: **myoglobin** (rises and falls first). Troponin stays up.", "NSTEMI: MONA + clopidogrel + beta blocker. **Angiography within 48 hours**."]}, {"t": 455, "title": "Stent vs CABG and discharge meds", "notes": ["CABG: **left main, 3-vessel, or 2-vessel in a diabetic**, or refractory symptoms.", "Discharge: aspirin or clopidogrel, **beta blocker, ACE inhibitor, statin**, nitrate as needed."]}, {"t": 517, "title": "Unstable angina and stress testing", "notes": ["**Any new angina is unstable**. Exercise ECG.", "Hold beta and calcium channel blockers before the test.", "**Old LBBB or digoxin: stress echo**. Cannot exercise: dobutamine or adenosine.", "Positive (symptoms, ST depression, BP drop): **angiography**."]}, {"t": 661, "title": "Post-MI complications by timing", "notes": ["Top cause of death after MI: **arrhythmia** (VFib).", "**Days 5 to 7, new systolic murmur: papillary muscle rupture** (MR).", "Sudden collapse: **free wall rupture**. Oxygen step-up RA to RV: **septal rupture**.", "Persistent ST elevation weeks later: **ventricular aneurysm**.", "Cannon A waves: **AV dissociation**, complete heart block.", "**Weeks later, pleuritic pain + fever: Dressler**, aspirin or NSAIDs."]}, {"t": 891, "title": "Pericarditis and other chest pain", "notes": ["**Diffuse ST elevation**, better leaning forward, rub. NSAIDs.", "Reproducible on palpation: costochondritis. After a viral illness + new murmur: myocarditis.", "Prinzmetal: rest pain, early morning, **woman with migraines**. Calcium channel blocker."]}, {"t": 976, "title": "Heart blocks, MAT, VT", "notes": ["Mobitz I (Wenckebach): **progressive PR lengthening then a dropped beat**.", "Third degree: **P and QRS unrelated**, cannon A waves.", "MAT: **3+ different P waves**, severe lung disease.", "VT: **unstable = shock**, stable = amiodarone or lidocaine."]}, {"t": 1182, "title": "WPW and flutter", "notes": ["WPW: **delta wave, short PR**. **Procainamide**.", "**Never give AV nodal blockers** in WPW (beta blocker, digoxin, verapamil, diltiazem).", "Flutter: **sawtooth**, atrial rate about 300. Rate control like AFib."]}, {"t": 1349, "title": "Torsades, SVT, hyperkalemia ECG", "notes": ["Torsades: long QT, **low K or Mg, TCA overdose**. IV magnesium.", "SVT: sudden onset and offset in a young adult. **Vagal maneuvers first**, then adenosine.", "Hyperkalemia: **peaked T**, wide QRS, long PR. Missed dialysis, crush, burns."]}, {"t": 1524, "title": "Electrical alternans and AFib", "notes": ["Tamponade: **low voltage + electrical alternans**, pulsus paradoxus.", "AFib: irregularly irregular, no P waves. Hyperthyroid, mitral disease.", "**Rate control** (beta blocker, digoxin) is first line."]}, {"t": 1692, "title": "Aortic stenosis vs HOCM", "notes": ["AS: crescendo-decrescendo, **softer with Valsalva**, pulsus parvus et tardus. Elderly or bicuspid valve. **Valve replacement**.", "HOCM: young athlete, **louder with Valsalva, softer with squat and hand grip**."]}, {"t": 1785, "title": "MVP, MR and congenital murmurs", "notes": ["MVP: **mid-systolic click**, louder with Valsalva.", "MR: holosystolic, **radiates to the axilla**.", "VSD: holosystolic in a child. PDA: **machinery**. ASD: **wide fixed split S2**.", "Mitral stenosis: **opening snap**, diastolic rumble, AFib. AR: blowing diastolic, **wide pulse pressure**."]}, {"t": 1932, "title": "Shortness of breath work-up", "notes": ["Suspected PE: **heparin first**.", "CHF + murmur: echo. Acute pulmonary edema: **nitrates, furosemide, morphine**.", "Young with CHF picture after a flu: **viral myocarditis** (Coxsackie B)."]}, {"t": 2021, "title": "Pulmonary hypertension vs CHF", "notes": ["Right heart cath: **wedge pressure high in CHF, normal in pulmonary hypertension**."]}, {"t": 2112, "title": "CHF: reversible causes and survival drugs", "notes": ["Reversible: **alcoholic cardiomyopathy** (stop drinking), **hemochromatosis** (phlebotomy).", "Survival: **ACE inhibitor, beta blocker, spironolactone** (class III to IV).", "**Digoxin helps symptoms, not survival**."]}, {"t": 2174, "title": "Chest x-ray patterns", "notes": ["Lobar consolidation + air bronchograms: **pneumonia**. Hyperlucent, flat diaphragms: **COPD**.", "Big heart + Kerley B lines: **CHF**. Cavity + air-fluid level: **abscess** (S aureus, anaerobes).", "Upper lobe cavity + hilar nodes: **TB**. Splayed carina: **left atrial enlargement** (mitral stenosis) or mediastinal nodes."]}, {"t": 2334, "title": "Pleural effusion", "notes": ["Over 1 cm on lateral decubitus: **tap it**.", "Transudate: **CHF, nephrotic, cirrhosis**. Exudate: **pneumonia, cancer**.", "Low glucose: empyema or **rheumatoid arthritis**. Lymphocytes: **TB**. Bloody: PE or cancer.", "Complicated (pH under 7.2, low glucose, bugs): **chest tube**.", "Light criteria: exudate if LDH ratio **over 0.6** or protein ratio **over 0.5**."]}, {"t": 2477, "title": "Pulmonary embolism", "notes": ["Risks: surgery, long travel, **cancer, nephrotic syndrome**.", "**Tachypnea** most common. Westermark sign, Hampton hump.", "**Heparin before imaging**. CT angiogram or V/Q. Bridge to warfarin.", "IVC filter when **anticoagulation is contraindicated** (falls, bleeding)."]}, {"t": 2603, "title": "ARDS", "notes": ["Causes: **sepsis**, aspiration, trauma, pancreatitis.", "Criteria: **PaO2/FiO2 under 200**, bilateral infiltrates, **wedge under 18** (not cardiac).", "Treat with **PEEP**, low tidal volume."]}, {"t": 2691, "title": "Pulmonary function tests", "notes": ["**Low FEV1/FVC = obstructive**. Normal ratio, both low = restrictive.", "**12%+ improvement with bronchodilator = asthma**.", "Low DLCO: **emphysema and interstitial lung disease**."]}, {"t": 2781, "title": "COPD management", "notes": ["Chronic bronchitis: productive cough **3 months for 2 years**.", "Outpatient: **ipratropium or tiotropium**, then beta agonist, then theophylline.", "Oxygen: **SpO2 under 88% or PaO2 under 55** (sooner if cor pulmonale).", "Exacerbation (sputum change): **steroids + antibiotic** + nebs.", "Best prognostic marker: **FEV1**. Mortality: **quit smoking, oxygen 18+ hours a day**. Target 88 to 92%."]}, {"t": 2963, "title": "New clubbing", "notes": ["Sudden clubbing in a smoker = **hypertrophic osteoarthropathy, lung cancer**. **Chest x-ray**."]}, {"t": 2994, "title": "Asthma steps and exacerbations", "notes": ["Mild intermittent: **SABA only**. Mild persistent: **add inhaled steroid**.", "Moderate: **add LABA**. Severe: add leukotriene modifier, oral steroid.", "**Normal or rising PCO2 during an attack = tiring, intubate**.", "ABPA: asthma complication, high IgE, eosinophils."]}, {"t": 3167, "title": "Occupational lung disease and sarcoidosis", "notes": ["Silicosis: **upper lobe, eggshell calcification**, higher **TB** risk, test yearly.", "Asbestosis: **lower lobe, pleural plaques**, mesothelioma, bronchogenic cancer.", "Farmer lung: hypersensitivity pneumonitis, thermophilic actinomycetes.", "Sarcoid: young Black woman, **hilar nodes, high ACE, high calcium** (vitamin D from granulomas). **Ophthalmology** (uveitis). Biopsy, steroids."]}, {"t": 3339, "title": "Pulmonary nodule", "notes": ["**Find an old x-ray first**.", "Benign: **popcorn (hamartoma)**, concentric calcification, young, small, smooth.", "Scary: spiculated, eccentric calcification, old smoker: **biopsy**."]}, {"t": 3455, "title": "Lung cancer types and paraneoplastic", "notes": ["Adenocarcinoma: **non-smokers, peripheral**, liver, bone, brain, adrenal mets.", "Squamous: central, **PTHrP hypercalcemia**.", "Small cell: central. **Pancoast** (shoulder pain, Horner, facial edema), **Lambert-Eaton** (better with use)."]}, {"t": 3597, "title": "SIADH and large cell; lung cancer treatment", "notes": ["Old smoker, low sodium, euvolemic: **SIADH from small cell**.", "Large cell: peripheral, **cavitates**, widely spread at diagnosis.", "Non-small cell: **resect**. Small cell: **chemo and radiation**."]}, {"t": 3655, "title": "Crohn vs ulcerative colitis", "notes": ["Crohn: **terminal ileum** (mimics appendicitis), skip lesions, transmural, granulomas, **fistulas (metronidazole)**, worse with smoking.", "UC: **rectum, continuous**, PSC, p-ANCA, **colon cancer risk**, cured by colectomy, smoking protective.", "5-ASA maintains, **steroids for flares**."]}, {"t": 3737, "title": "IBD imaging and skin", "notes": ["**Toxic megacolon**: dilated colon, surgical emergency.", "String sign: **Crohn**.", "**Pyoderma gangrenosum**: treat the IBD, no antibiotics. Erythema nodosum: shins, UC and sarcoid."]}, {"t": 3824, "title": "Liver enzyme patterns", "notes": ["**AST over ALT (2:1), high GGT: alcohol**. ALT over AST in thousands: **viral**.", "Both in thousands after shock or surgery: **ischemic hepatitis**.", "High direct bilirubin: **obstruction**. High indirect: **hemolysis**, Gilbert, Crigler-Najjar.", "High ALP + GGT: biliary. **High ALP, normal GGT and calcium: Paget** (hat size, hearing loss)."]}, {"t": 3959, "title": "Autoimmune liver, hemochromatosis, Wilson", "notes": ["**Anti-mitochondrial: PBC** (no steroids). **Anti-smooth muscle: autoimmune hepatitis** (steroids work).", "Hemochromatosis: **high iron and ferritin**, diabetes, bronze skin. Phlebotomy.", "Wilson: **low ceruloplasmin**, high urine copper, psych symptoms, **Kayser-Fleischer rings**."]}, {"t": 4023, "title": "Meningitis", "notes": ["S pneumoniae, N meningitidis, H flu. **Listeria in old, young, immunocompromised: add ampicillin**.", "After neurosurgery: **staph, vancomycin**. TB meningitis: RIPE + steroids. **Lyme meningitis: IV ceftriaxone**.", "**Antibiotics first**, check for raised ICP before LP.", "Close contacts of meningococcus: **rifampin**."]}, {"t": 4134, "title": "Pneumonia bugs by clue", "notes": ["Young healthy: **Mycoplasma** (cold agglutinins), macrolide.", "Hospitalized recently: **Pseudomonas, Klebsiella, E coli**.", "COPD smoker: **H flu**. Alcoholic, **currant jelly**: Klebsiella. **Hot tub + diarrhea + confusion: Legionella**.", "After flu: **S aureus**. Cow birth: **Q fever**. Skinned a rabbit: **tularemia**."]}, {"t": 4291, "title": "Tuberculosis", "notes": ["Positive PPD: **chest x-ray**. Positive x-ray: sputum AFB. **3 negative sputums** to rule out.", "Active: 4 drugs, narrow by sensitivities.", "Exposure prophylaxis only for **children under 4**.", "Rifampin: orange fluids, **CYP450 inducer**. INH: **neuropathy, give B6**. Ethambutol: **optic neuritis**. Pyrazinamide: high uric acid."]}, {"t": 4415, "title": "Endocarditis", "notes": ["Acute: **S aureus**. Subacute: **viridans strep**, mitral valve.", "IV drug use: **tricuspid**, right-sided murmurs louder on inspiration.", "Blood cultures, then echo. Top cause of death: **heart failure** from valve destruction.", "Prophylaxis: **prosthetic valve, prior endocarditis, uncorrected congenital lesion**.", "**Strep bovis: colonoscopy**."]}, {"t": 4534, "title": "HIV clues and treatment", "notes": ["Mono-like illness: **test for HIV**. Young Bell palsy, unexplained low platelets, thrush, shingles.", "Zidovudine: **macrocytic anemia**, leukopenia. Abacavir: hypersensitivity. Efavirenz: psych symptoms. Indinavir: stones.", "Needlestick from HIV-positive: **3-drug regimen for 4 weeks**."]}, {"t": 4708, "title": "PCP in HIV", "notes": ["Exertional dyspnea, dry cough, **bilateral infiltrates, high LDH**.", "Diagnosis: **bronchoscopy with BAL**. TMP-SMX (dapsone or pentamidine if sulfa allergic).", "**Steroids if PaO2 under 70**. Prophylaxis at **CD4 under 200**."]}, {"t": 4802, "title": "HIV diarrhea and brain lesions", "notes": ["CMV: biopsy shows **inclusions**. Cryptosporidium: **acid-fast oocysts**. MAC: diagnosis of exclusion.", "**Multiple ring-enhancing = toxo**, single = CNS lymphoma. Treat both with **pyrimethamine-sulfadiazine** first, biopsy if no change.", "Temporal lobe seizure + **RBCs in CSF = HSV**: acyclovir now.", "Cryptococcus: India ink, amphotericin. **PML**: JC virus, MS-like, no treatment but ART."]}, {"t": 5047, "title": "Neutropenic fever", "notes": ["**No rectal exam**.", "Single high fever or sustained low-grade, **ANC under 500**.", "Pseudomonas, MRSA (ports). **Blood cultures, then ceftazidime or cefepime**. Add vancomycin for lines, **amphotericin if no better in 5 to 7 days**."]}, {"t": 5137, "title": "Tick-borne and branching bacteria", "notes": ["Lyme: doxycycline, **amoxicillin under 8**.", "RMSF: palms and soles rash. **Doxycycline even in children**.", "Ehrlichiosis: tick bite, **no rash, low platelets**. Doxycycline.", "Nocardia: **partially acid-fast**, aerobic, lungs, TMP-SMX. Actinomyces: anaerobic, **penicillin**."]}, {"t": 5287, "title": "Sodium disorders", "notes": ["Hyponatremia: check osmolality, then volume. Euvolemic = **SIADH** (smoker: chest x-ray).", "Hypovolemic: normal saline. **3% saline only if seizing or under 120**. Otherwise fluid restrict.", "Correct slowly: **central pontine myelinolysis**. Hypernatremia too fast: cerebral edema."]}, {"t": 5416, "title": "Calcium and potassium", "notes": ["Hypocalcemia: perioral numbness, Chvostek, Trousseau, **long QT**. Hypercalcemia: bones, stones, groans, psych.", "Hypokalemia: weakness, constipation, **U waves**.", "Hyperkalemia: **calcium gluconate first**, then insulin + glucose, albuterol, binder, diuretic. Dialysis if severe."]}, {"t": 5509, "title": "Acid-base patterns", "notes": ["Metabolic alkalosis: **urine chloride**. Low = vomiting or NG suction. High = hyperaldosteronism.", "Metabolic acidosis: anion gap (8 to 12). Non-gap: **diarrhea, RTA**."]}, {"t": 5596, "title": "Renal tubular acidosis", "notes": ["Type 1 (distal): **lithium**, alkaline urine, low K. **Give bicarb**.", "Type 2 (proximal): **multiple myeloma**, low K. Bicarb does not help, give thiazide + potassium.", "Type 4: **diabetes**, low aldosterone, **high K**. **Fludrocortisone**."]}, {"t": 5740, "title": "Acute kidney injury", "notes": ["Creatinine up **25% or 0.5**. BUN to creatinine ratio, **FeNa** (use **FeUrea on diuretics**).", "Pre-renal: give fluids, fix the cause."]}, {"t": 5830, "title": "Intrinsic AKI causes", "notes": ["**Muddy brown casts: ATN** (aminoglycosides, amphotericin, cisplatin, ischemia).", "**Urine eosinophils + fever + rash after a drug: AIN**. Stop the drug, steroids.", "Rhabdo: high CK, **dipstick blood, no RBCs**. **Check potassium or ECG first**.", "**Envelope crystals: ethylene glycol**. Creatinine up **2 to 3 days after contrast**: contrast nephropathy."]}, {"t": 5945, "title": "Dialysis indications and CKD", "notes": ["**AEIOU**: acidosis, potassium, ethylene glycol or lithium, overload, **uremic pericarditis or confusion**. A high creatinine alone is not one.", "CKD: **diabetes then hypertension**. Death: cardiovascular.", "Complications: anemia (EPO), **high K and phosphate, low calcium**, secondary hyperparathyroidism, **uremic bleeding**."]}, {"t": 6060, "title": "Hematuria and nephritic syndrome", "notes": ["**Painless hematuria = cancer** until proven otherwise. Terminal hematuria: bladder.", "Dysmorphic RBCs: glomerular. Nephritic: hematuria, HTN, mild proteinuria, azotemia.", "**1 to 2 days after a URI: IgA nephropathy**. **1 to 2 weeks after strep throat or impetigo: PSGN**.", "**Hemoptysis: Goodpasture**. **Deafness: Alport**."]}, {"t": 6175, "title": "HSP, HUS, TTP, vasculitis", "notes": ["Child with purpura, arthralgia, abdominal pain: **HSP**.", "After hamburger + diarrhea: **HUS**.", "TTP (ticlopidine): **plasmapheresis, never platelets**. Normal PT and PTT (vs DIC).", "c-ANCA kidney + lung + sinus: **GPA (Wegener)**. p-ANCA + asthma + eosinophils: **Churg-Strauss**. No lung, hep B: **PAN**."]}, {"t": 6268, "title": "Kidney stones", "notes": ["Best test: **non-contrast CT**. Most common: **calcium oxalate**.", "Family history in a child: **cystine**. **Alkaline urine + urease bugs (Proteus): struvite**.", "Leukemia on chemo: **uric acid**. After bowel resection: **oxalate**.", "Small: fluids, pass it. Medium: **lithotripsy**. Large: surgery."]}, {"t": 6384, "title": "Nephrotic syndrome", "notes": ["First: **repeat the UA**. Nephrotic: **protein over 3.5 g**, low albumin, edema, high lipids, fatty casts.", "Children: **minimal change**. Heroin or HIV: **FSGS**. Hep B or C: membranous or membranoproliferative.", "**New flank pain: renal vein thrombosis** (they lose clotting factors)."]}, {"t": 6469, "title": "Microcytic anemias", "notes": ["Iron deficiency: low iron, **high TIBC**, low ferritin, high RDW.", "Chronic disease: low iron, **low TIBC**, normal or high ferritin.", "Thalassemia: **MCV very low, normal RDW**.", "Sideroblastic: high iron and ferritin, **ring sideroblasts**, **isoniazid**."]}, {"t": 6592, "title": "Macrocytic anemias", "notes": ["Hypersegmented neutrophils: **folate (normal MMA)** or **B12 (high MMA, neuro signs)**.", "Acanthocytes: **liver disease**."]}, {"t": 6652, "title": "Hemolytic anemias", "notes": ["High LDH and indirect bilirubin, **low haptoglobin**.", "Sickle crisis: hypoxia, dehydration, acidosis. Aplastic crisis: parvovirus.", "Cold (IgM): **Mycoplasma**, blue fingers. Warm (IgG): drugs, cancer.", "Spherocytosis: **high MCHC**, splenomegaly, gallstones, splenectomy.", "Dark morning urine, Budd-Chiari: **PNH**. **Primaquine, sulfa, fava beans: G6PD**."]}, {"t": 6773, "title": "Bleeding disorders", "notes": ["Only low platelets in a young woman: **ITP**. Prednisone, then splenectomy.", "High bleeding time + PTT: **von Willebrand** (carries factor VIII).", "Male with bleeding, high PTT that **corrects with mixing: hemophilia**. Not corrected: inhibitor.", "Antibiotics + no greens: **vitamin K deficiency**.", "Liver disease: **PT rises first** (factor VII). VIII and vWF are not made in the liver."]}, {"t": 6942, "title": "DIC, TTP, HIT, clotting disorders", "notes": ["Schistocytes + **high PT and PTT, low fibrinogen**: DIC (sepsis, obstetric, **AML M3**). Treat the cause.", "Schistocytes + **normal PT and PTT**: TTP or HUS. **Plasmapheresis, no platelets**.", "Clot + low platelets **about 7 days post-op: HIT**. Stop heparin, direct thrombin inhibitor.", "Unprovoked clot in the elderly: **look for cancer**. **Skin necrosis on warfarin: protein C or S deficiency**.", "Factor V Leiden most common. **Antithrombin III deficiency: heparin fails**."]}]}, {"key": "d1", "id": "BfRBmmaqT5s", "who": "Divine Intervention", "title": "Episode 29: Medicine Shelf Review, Session 1", "len": 7041, "approx": true, "label": "D1", "c": "d", "short": "Divine Ep 29", "rail": "Divine Intervention Ep 29", "pdf": "Divine%20Intervention%20Ep29.pdf", "sections": [{"t": 192, "title": "Mitral stenosis murmur; porphyria cutanea tarda", "notes": ["Opening snap + diastolic rumble: **mitral stenosis**. Louder with **expiration, left lateral decubitus**, increased venous return.", "Blisters on dorsal hands + hirsutism + high LFTs: **porphyria cutanea tarda** (uroporphyrinogen decarboxylase). **Phlebotomy, hydroxychloroquine**, stop alcohol, check hep C."], "p": 3}, {"t": 457, "title": "Hypoglycemia causes", "notes": ["Whipple triad. **Insulinoma: high insulin + high C-peptide**. Exogenous insulin: **high insulin, low C-peptide**. Sulfonylurea: high C-peptide, **positive screen**.", "Acute: oral glucose if awake, **IV dextrose or IM glucagon** if not."], "p": 5}, {"t": 590, "title": "Diarrhea bugs by exposure", "notes": ["Pork: **Yersinia** (pseudoappendicitis). Shellfish: Vibrio parahaemolyticus. **Rice-water stools: cholera**.", "Tiny inoculum, bloody: **Shigella**. Eggs, poultry: **Salmonella**. 2 hours after rice: **B cereus**.", "Travel to Mexico: **ETEC**. After clindamycin: **C diff**. Home-canned food: **botulism**."], "p": 6}, {"t": 855, "title": "Lead poisoning and sideroblastic anemia", "notes": ["Old house + ring sideroblasts: **lead**. High iron, high ferritin, low TIBC.", "**Chelation** (succimer, EDTA, dimercaprol). B6 for sideroblastic anemia from isoniazid."], "p": 8}, {"t": 987, "title": "PCP in the immunosuppressed", "notes": ["Bilateral ground glass on high-dose immunosuppressants: **Pneumocystis jirovecii**. Silver stain. **High LDH**.", "TMP-SMX treats and prevents. **Add steroids if PaO2 under 70 or A-a over 35**. BAL to diagnose."], "p": 9}, {"t": 1120, "title": "Kidney stones by shape", "notes": ["Envelope: **calcium oxalate**. Coffin lid: **struvite** (Proteus). Radiolucent: **uric acid**. Hexagon: **cystine**.", "Best test: **non-contrast CT**. Fluids, analgesia, tamsulosin. Big stones: lithotripsy or ureteroscopy."], "p": 10}, {"t": 1252, "title": "Osteochondroma, CO poisoning", "notes": ["Painless mushroom-shaped bony mass near the knee: **osteochondroma**.", "Found unconscious in winter, cherry red skin: **carbon monoxide**. **Co-oximetry carboxyhemoglobin**. **100% oxygen**, hyperbaric if severe. Pulse ox falsely normal."], "p": 11}, {"t": 1517, "title": "Contrast nephropathy, gadolinium, metformin", "notes": ["Creatinine up after CT contrast: prevent with **IV fluids**. Hold **metformin** around contrast.", "Skin fibrosis after MRI in kidney failure: **nephrogenic systemic fibrosis** (gadolinium)."], "p": 13}, {"t": 1650, "title": "Drug-induced edema; SJS/TEN", "notes": ["Ankle edema from **calcium channel blockers** and hydralazine: precapillary arteriolar dilation. Lower the dose or add ACE inhibitor.", "Targetoid lesions, mucosa, **Nikolsky positive**, new allopurinol: **SJS** (under 10%). **Stop the drug**, burn-unit style care."], "p": 14}, {"t": 1915, "title": "HHS and DKA", "notes": ["Glucose 650, normal pH: **HHS**. Fluids first, then insulin.", "Total body potassium is low. Confusion after **rapid correction: cerebral edema**."], "p": 16}, {"t": 2047, "title": "Carcinoid syndrome", "notes": ["Wheeze + flushing + **TR and pulmonic stenosis**: carcinoid with liver mets.", "**Urine 5-HIAA**, then imaging. **Octreotide**. Niacin deficiency: **pellagra**."], "p": 17}, {"t": 2180, "title": "Anemia in the elderly", "notes": ["Older man with iron deficiency: **colonoscopy** to rule out colon cancer.", "Transfuse under 7 g/dL (under 8 with cardiac disease)."], "p": 18}, {"t": 2312, "title": "Typhoid fever", "notes": ["Travel, fever, then abdominal pain, **rose spots**, relative bradycardia: **Salmonella typhi**.", "Ceftriaxone or fluoroquinolone (azithromycin)."], "p": 19}, {"t": 2445, "title": "Septic arthritis", "notes": ["**S aureus** most common. **Sickle cell: Salmonella**. Young woman + pustules: **gonorrhea**.", "**Arthrocentesis**: WBC over 50,000. Drain + IV antibiotics. Gonorrhea: ceftriaxone + cover chlamydia."], "p": 20}, {"t": 2577, "title": "Pertussis; ACE inhibitor cough", "notes": ["Coughing fits + subconjunctival hemorrhage: **pertussis**. **Macrolide**, prophylaxis for close contacts.", "Cough after starting ramipril: **switch to an ARB** (bradykinin)."], "p": 21}, {"t": 2710, "title": "AV blocks", "notes": ["First degree: long PR. Mobitz I: progressive PR then drop. **Mobitz II and third degree: pacemaker**.", "Symptomatic: **atropine**, then pacing. Avoid AV nodal blockers."], "p": 22}, {"t": 2842, "title": "Acromegaly", "notes": ["Coarse face, large hands, **low EF**: acromegaly.", "**IGF-1**, then glucose suppression test, then pituitary MRI. **Transsphenoidal surgery**, octreotide, pegvisomant.", "Death: **cardiovascular**."], "p": 23}, {"t": 2975, "title": "Chagas disease", "notes": ["Dysphagia + trypomastigotes: **Trypanosoma cruzi** (reduviid bug).", "Megaesophagus, megacolon, **dilated cardiomyopathy**. Benznidazole or nifurtimox."], "p": 24}, {"t": 3107, "title": "Anemia of chronic disease", "notes": ["Long-standing RA: **high ferritin, low iron, low TIBC**. Hepcidin traps iron.", "Treat the underlying disease."], "p": 25}, {"t": 3240, "title": "Toxic shock syndrome", "notes": ["Nasal packing + shock + fever + rash: **TSS** (S aureus TSST-1, strep pyrogenic toxin).", "Superantigen. **Remove packing, fluids, clindamycin + vancomycin**."], "p": 26}, {"t": 3372, "title": "CKD complications", "notes": ["Metabolic acidosis, **high K and phosphate, low calcium**, secondary hyperparathyroidism, **anemia** (EPO).", "Slow progression: **ACE inhibitor or ARB**, SGLT2 inhibitor. Dialysis for AEIOU."], "p": 27}, {"t": 3505, "title": "Osteosarcoma; AERD", "notes": ["Rb gene, **Paget disease, teriparatide**: **osteosarcoma**, sunburst, Codman triangle.", "Asthma + nasal polyps + aspirin sensitivity: **AERD**. Avoid NSAIDs, leukotriene modifiers, desensitization."], "p": 28}, {"t": 4035, "title": "SVT and PE ECG", "notes": ["SVT: **vagal maneuvers, then adenosine**, then beta or calcium blocker. **Unstable: synchronized cardioversion**.", "Most common ECG finding in PE: **sinus tachycardia**."], "p": 32}, {"t": 4168, "title": "Eczema and eczema herpeticum", "notes": ["Scaly patches + allergic rhinitis: **atopic dermatitis**. Moisturizer, **topical steroid**.", "Umbilicated vesicles on eczema: **eczema herpeticum**, **acyclovir**."], "p": 33}, {"t": 4300, "title": "Hypercalcemia management", "notes": ["Stones, bones, groans, psych + dry: **IV normal saline first**.", "Then **calcitonin** (fast) and **bisphosphonate** (lasting). Loop diuretic only after volume restored."], "p": 34}, {"t": 4433, "title": "H pylori and PUD", "notes": ["Tests: **urea breath test, stool antigen**, biopsy (urease).", "Triple therapy: PPI + clarithromycin + amoxicillin (or quadruple). Duodenal ulcer pain better with food."], "p": 35}, {"t": 4565, "title": "Thalassemias and hemolysis", "notes": ["Beta minor: **high HbA2**. Alpha minor: normal electrophoresis.", "Beta major: symptoms at **6 months**. HbH: 3 alpha genes deleted. **Hb Barts: hydrops**.", "Hemolysis: **pigment gallstones**, parvovirus aplastic crisis. Thalassemia is microcytic."], "p": 36}, {"t": 4830, "title": "Coccidioidomycosis", "notes": ["Tucson, fever, arthralgias, **erythema nodosum**: valley fever.", "**Spherules with endospores**. Self-limited, fluconazole if severe."], "p": 38}, {"t": 4963, "title": "PSGN", "notes": ["Periorbital edema + hematuria + HTN **2 to 3 weeks after skin or throat strep**.", "**Low C3**, ASO or anti-DNase B. **Type III** hypersensitivity. Supportive."], "p": 39}, {"t": 5095, "title": "Ewing sarcoma; parapneumonic effusion", "notes": ["t(11;22), **onion skin**, small round blue cells: **Ewing**.", "Complicated effusion or empyema: **pH under 7.2, glucose under 60, positive gram stain: chest tube**."], "p": 40}, {"t": 5493, "title": "Ventricular fibrillation and pulseless arrest", "notes": ["VT or VFib: stable = amiodarone. **Unstable = cardioversion. Pulseless = defibrillate + CPR + epinephrine**.", "Death right after MI: **arrhythmia**."], "p": 43}, {"t": 5625, "title": "Pemphigus vs bullous pemphigoid", "notes": ["**Pemphigus vulgaris**: oral ulcers, **Nikolsky positive**, anti-desmoglein, type II. **Direct immunofluorescence**. Steroids, rituximab.", "**Bullous pemphigoid**: elderly, itchy, **no mouth lesions, Nikolsky negative**, hemidesmosomes. Topical steroids."], "p": 44}, {"t": 5758, "title": "Hyperaldosteronism", "notes": ["Primary (Conn): **high aldosterone, low renin**. Screen: ratio. Confirm: **salt loading**. Then CT, adrenal vein sampling.", "Secondary: **both high** (renal artery stenosis, CHF).", "Adenoma: surgery. Hyperplasia: **spironolactone**."], "p": 45}, {"t": 5890, "title": "IBS and cold vs warm AIHA", "notes": ["IBS (Rome): pain related to stool change. **Normal labs**. Young women.", "Cold (IgM): **Mycoplasma, EBV**, avoid cold. Warm (IgG): CLL, lupus, drugs, **steroids**."], "p": 46}, {"t": 6155, "title": "Schistosomiasis", "notes": ["Swam in the Nile: **Schistosoma haematobium** (hematuria) or mansoni (portal hypertension).", "**Eosinophilia**, **squamous cell bladder cancer**. **Praziquantel**."], "p": 48}, {"t": 6288, "title": "IgA nephropathy vs PSGN; spinal stenosis", "notes": ["IgA: hematuria **1 to 2 days** after URI, **normal complement**. PSGN: 2 to 3 weeks, low C3.", "Leg pain worse in extension, **better bent forward**: **spinal stenosis**. MRI. PT, surgery if severe."], "p": 49}, {"t": 6553, "title": "Mitral stenosis management", "notes": ["**Rheumatic heart disease**. **Echo**.", "Beta blocker, diuretic, anticoagulate if AFib. **Balloon valvotomy** or replacement."], "p": 51}, {"t": 6818, "title": "Adrenal insufficiency", "notes": ["Primary (Addison): **hyperpigmentation**, high ACTH, **low aldosterone, high renin**, high K.", "Secondary: **no pigment**, low ACTH, normal aldosterone.", "Hydrocortisone (+ fludrocortisone in primary). **Meningococcemia + adrenal crash: Waterhouse-Friderichsen**."], "p": 53}, {"t": 6951, "title": "Diverticulitis", "notes": ["Fever + **LLQ pain** + leukocytosis. **CT with contrast**. Avoid colonoscopy or barium acutely.", "Ciprofloxacin + metronidazole, or amoxicillin-clavulanate. **Pneumaturia, recurrent UTI: colovesical fistula**."], "p": 54}]}, {"key": "d2", "id": "B4EDgnzhtuE", "who": "Divine Intervention", "title": "Episode 30: Medicine Shelf Review, Session 2", "len": 10301, "approx": true, "label": "D2", "c": "d", "short": "Divine Ep 30", "rail": "Divine Intervention Ep 30", "pdf": "Divine%20Intervention%20Ep30.pdf", "sections": [{"t": 60, "title": "B12 vs folate", "notes": ["B12: **high methylmalonic acid + homocysteine**, neuro signs (dorsal columns). Folate: **only homocysteine high**.", "Causes: pernicious anemia, ileal resection, metformin, vegans. Folate: alcohol, pregnancy, methotrexate."], "p": 55}, {"t": 176, "title": "HIV prophylaxis by CD4", "notes": ["**Under 200: TMP-SMX** (PCP). **Under 100: TMP-SMX** also covers toxo (if IgG positive).", "Under 50: **azithromycin** (MAC) if not on ART."], "p": 56}, {"t": 293, "title": "Diabetes insipidus and hypernatremia", "notes": ["Water deprivation: urine stays dilute. **Desmopressin corrects = central**. No change = **nephrogenic** (lithium).", "Hypovolemic hypernatremia: **normal saline first**, then free water. Correct **no faster than 10 to 12 per day**."], "p": 57}, {"t": 410, "title": "Osteoarthritis", "notes": ["X-ray: **joint space narrowing, osteophytes, subchondral sclerosis, cysts**. Heberden and Bouchard nodes.", "Fluid: **under 2000 WBC**. Weight loss, exercise, **acetaminophen then NSAIDs**, injections, replacement."], "p": 58}, {"t": 526, "title": "Legionella and atypical pneumonia", "notes": ["Conference or hotel, fever, dry cough, **diarrhea, hyponatremia**: **Legionella**.", "**Urine antigen**. Macrolide or fluoroquinolone. Mycoplasma most common atypical."], "p": 59}, {"t": 643, "title": "Mitral valve prolapse", "notes": ["**Mid-systolic click** at apex. Marfan, Ehlers-Danlos, ADPKD. **Myxomatous degeneration**.", "Echo. **Squat or hand grip: click later, murmur softer**. Valsalva or standing: earlier, louder."], "p": 60}, {"t": 760, "title": "Seborrheic dermatitis", "notes": ["Scaly, greasy yellow crusts in winter on scalp, eyebrows, **nasolabial folds**. Malassezia.", "**Ketoconazole or selenium**, mild topical steroid."], "p": 61}, {"t": 876, "title": "Pheochromocytoma", "notes": ["Episodic headache, sweating, palpitations, HTN. **MEN 2A and 2B, VHL, NF1**.", "**Plasma or urine metanephrines**, then CT or MRI.", "**Alpha blocker (phenoxybenzamine) before beta blocker**, then surgery."], "p": 62}, {"t": 993, "title": "Lower GI bleed and folate", "notes": ["Elderly LGIB: **diverticulosis** (painless), angiodysplasia. **Colonoscopy**.", "Folate deficiency: alcoholics, pregnancy. Methotrexate, TMP-SMX inhibit folate. **Leucovorin rescue**."], "p": 63}, {"t": 1226, "title": "CMV in the immunocompromised", "notes": ["CD4 under 50: **retinitis** (pizza pie), colitis, esophagitis (linear ulcers).", "**Owl eye inclusions**. **Ganciclovir**, foscarnet. Congenital: **periventricular calcifications**."], "p": 65}, {"t": 1343, "title": "HIV nephropathy and AIN", "notes": ["HIV + nephrotic: **collapsing FSGS**. ART, ACE inhibitor.", "Indinavir: **stones**. Fever + rash + eosinophilia after a drug: **AIN**."], "p": 66}, {"t": 1460, "title": "Vitamin D, osteomalacia, rickets", "notes": ["Low vitamin D: **low calcium and phosphate, high PTH, high ALP**.", "Children: rickets. Adults: **osteomalacia** (Looser zones). Vitamin D + calcium."], "p": 67}, {"t": 1576, "title": "Aspiration pneumonia and CURB-65", "notes": ["Alcohol, seizures, stroke, dysphagia: **right lower lobe** (upright), anaerobes. **Clindamycin or amoxicillin-clavulanate**.", "CURB-65: **0 to 1 home, 2 admit, 3+ ICU**."], "p": 68}, {"t": 1693, "title": "Pulmonary arterial hypertension drugs", "notes": ["**Endothelin antagonists (bosentan)**, PDE5 inhibitors (sildenafil), prostacyclins (epoprostenol), calcium channel blockers if vasoreactive."], "p": 69}, {"t": 1810, "title": "Actinic keratosis", "notes": ["Sandpaper scaly macules on sun-exposed skin. **5-FU, cryotherapy**.", "Risk of **squamous cell carcinoma**."], "p": 70}, {"t": 1926, "title": "Hyperparathyroidism types", "notes": ["Primary: **high calcium, high PTH, low phosphate** (adenoma).", "Secondary: **low calcium, high PTH** (CKD, vitamin D). Tertiary: **autonomous PTH, high calcium** after long CKD.", "Hypercalcemia: **IV fluids**, calcitonin, bisphosphonates."], "p": 71}, {"t": 2043, "title": "Appendicitis", "notes": ["Periumbilical pain migrating to **McBurney point**. Rovsing, psoas, obturator signs.", "Imaging: **CT adults, ultrasound in kids and pregnancy**. Appendectomy."], "p": 72}, {"t": 2160, "title": "Aplastic anemia and Fanconi", "notes": ["Drugs: **chloramphenicol, carbamazepine, benzene**. Viruses: parvovirus, hepatitis, EBV.", "Fanconi anemia: DNA repair defect, **absent thumbs**, pancytopenia. Fanconi syndrome: proximal tubule wasting."], "p": 73}, {"t": 2276, "title": "Toxoplasmosis in HIV", "notes": ["CD4 under 100 + **multiple ring-enhancing lesions**. **Pyrimethamine + sulfadiazine + leucovorin**.", "Prophylaxis: TMP-SMX. Congenital: **diffuse calcifications, chorioretinitis, hydrocephalus**."], "p": 74}, {"t": 2393, "title": "Lupus nephritis and osteoporosis", "notes": ["**Anti-dsDNA**: lupus nephritis, type III. Steroids, **mycophenolate or cyclophosphamide**.", "Osteoporosis: **DEXA 65+ women**. Calcium, vitamin D, weight-bearing, **bisphosphonates**. Hip and vertebral fractures."], "p": 75}, {"t": 2626, "title": "Pneumonia by sputum and setting", "notes": ["**Currant jelly: Klebsiella** (alcoholics). **Rust: S pneumoniae**.", "Post-viral cavity: **S aureus**. Ventilator: **Pseudomonas**."], "p": 77}, {"t": 2743, "title": "Myocarditis; TEN", "notes": ["JVD and exercise intolerance after a URI: **viral myocarditis** (Coxsackie B). South America: **Chagas**.", "Skin sloughing over 30%: **TEN** (allopurinol). Burn unit, stop the drug."], "p": 78}, {"t": 2976, "title": "Hypocalcemia", "notes": ["After thyroid surgery: **hypoparathyroidism**. Tetany, **long QT**, Chvostek, Trousseau.", "Recurrent infections + hypocalcemia: **DiGeorge**."], "p": 80}, {"t": 3093, "title": "Acute pancreatitis", "notes": ["Epigastric pain to the back. **Gallstones and alcohol**, high TG, hypercalcemia.", "**Lipase** (more specific). Grey Turner, Cullen.", "**Aggressive IV fluids**, pain control, early feeding. Gallstone: cholecystectomy same admission."], "p": 81}, {"t": 3210, "title": "PNH; Cryptosporidium", "notes": ["Morning red urine + **hepatic vein thrombosis**: **PNH** (PIGA, CD55/59). **Flow cytometry**. Eculizumab.", "HIV + watery diarrhea + **acid-fast oocysts**: Cryptosporidium. ART, nitazoxanide."], "p": 82}, {"t": 3443, "title": "ATN", "notes": ["**Muddy brown casts** after contrast or gentamicin."], "p": 84}, {"t": 3560, "title": "Rheumatoid arthritis", "notes": ["**Anti-CCP** more specific than RF. HLA-DR4.", "MCP and PIP, **spares DIP**, swan neck, boutonniere, ulnar deviation. X-ray: **erosions**.", "Caplan: RA + pneumoconiosis. Felty: **RA + splenomegaly + neutropenia**."], "p": 85}, {"t": 3677, "title": "Strep vs mono; Centor", "notes": ["Mono: **posterior nodes, splenomegaly**, rash with amoxicillin. Strep: anterior nodes, exudate.", "Centor 0 to 1: no test. 2 to 3: rapid strep. **4: treat**. Penicillin."], "p": 86}, {"t": 3793, "title": "Endocarditis", "notes": ["Most common: **S aureus**. **Libman-Sacks** (lupus): both sides of the mitral valve. Right side: IV drug use.", "Janeway lesions, Osler nodes, Roth spots, splinters. **Blood cultures x3, echo**."], "p": 87}, {"t": 3910, "title": "Psoriasis and thyroid storm", "notes": ["Salmon plaques + silver scale on **extensor** surfaces. Topical steroids, vitamin D analogues, biologics. **Psoriatic arthritis**: DIP, pencil-in-cup.", "Fever + AFib + Graves: **thyroid storm**. **Beta blocker, PTU, iodine, steroids**."], "p": 88}, {"t": 4143, "title": "Langerhans, Kaposi, AIN", "notes": ["**Birbeck granules (tennis racket)**: Langerhans cell histiocytosis.", "HIV + purple macules + SBO: **Kaposi sarcoma, HHV-8**. ART.", "Fever + rash + eosinophiluria after nafcillin: **AIN**, stop drug."], "p": 90}, {"t": 4493, "title": "Lupus and antiphospholipid", "notes": ["SOAP BRAIN MD. **ANA sensitive, anti-dsDNA and anti-Smith specific**.", "Drug-induced: **hydralazine, procainamide, isoniazid** (anti-histone).", "APS: clots + miscarriage, **false-positive VDRL**, prolonged PTT. Death in lupus: **renal, infection, CV**."], "p": 93}, {"t": 4610, "title": "Lung abscess; pericarditis", "notes": ["Abscess: **aspiration** (anaerobes), S aureus, Klebsiella. Clindamycin.", "Pericarditis: pleuritic pain **better sitting forward**. **Diffuse ST elevation, PR depression**. NSAIDs + colchicine."], "p": 94}, {"t": 4843, "title": "Basal cell carcinoma; Hashimoto", "notes": ["**Pearly papule + telangiectasias**, upper lip, farmer. Mohs.", "Hashimoto: cold intolerance, **anti-TPO**, lymphocytes + Hurthle cells. **Levothyroxine**. Lymphoma risk."], "p": 96}, {"t": 5077, "title": "Variceal bleeding", "notes": ["Cirrhosis + hematemesis: **varices**.", "Acute: **2 large IVs, octreotide, ceftriaxone, endoscopic banding**. TIPS if refractory.", "Prophylaxis: **non-selective beta blocker** (propranolol, nadolol)."], "p": 98}, {"t": 5193, "title": "Bleeding disorders", "notes": ["Platelet bleeds: mucosal, petechiae. Factor bleeds: **joints, deep muscle**.", "Hemophilia A (VIII), B (IX): **high PTT**. Bernard-Soulier: **GPIb**, big platelets. Glanzmann: **GPIIb/IIIa**."], "p": 99}, {"t": 5310, "title": "Candida", "notes": ["Thrush risk: inhaled steroids, HIV, diabetes, antibiotics.", "Oral: **nystatin or clotrimazole**. Esophageal: fluconazole. Invasive: **echinocandin** or amphotericin."], "p": 100}, {"t": 5427, "title": "Pleural effusion and Light criteria", "notes": ["Exudate: **protein ratio over 0.5, LDH over 0.6**, LDH over 2/3 upper limit.", "Transudate: CHF, cirrhosis, nephrotic. **Chylothorax: high triglycerides** (thoracic duct).", "Dull to percussion, **decreased fremitus**."], "p": 101}, {"t": 5543, "title": "Acute mitral regurgitation", "notes": ["Holosystolic apical murmur after MI: **papillary muscle rupture**. Acute = pulmonary edema, shock.", "Echo. **Surgery**, afterload reduction."], "p": 102}, {"t": 5660, "title": "Pressure ulcers", "notes": ["Stage 1: non-blanching. 2: partial thickness. 3: full thickness. 4: **bone or tendon**.", "**Reposition every 2 hours**, nutrition. Debridement for 3 to 4. Chronic wound: **Marjolin ulcer**."], "p": 103}, {"t": 5777, "title": "Type 1 diabetes and GI bleed", "notes": ["**Anti-GAD**, insulin antibodies. Diagnose: A1c 6.5, fasting 126, random 200 + symptoms.", "Yearly: **eye exam, foot exam, urine albumin**.", "GI bleed: 2 large IVs, fluids, **transfuse under 7**, PPI, endoscopy."], "p": 104}, {"t": 6010, "title": "Antiplatelets and vWD", "notes": ["Aspirin: COX. Clopidogrel: **ADP receptor**. Abciximab: IIb/IIIa.", "Abnormal ristocetin: **vWD and Bernard-Soulier**. vWD: high PTT. **Desmopressin**."], "p": 106}, {"t": 6127, "title": "HSV", "notes": ["HSV-1: oral, **temporal lobe encephalitis** (RBCs in CSF). HSV-2: genital.", "**PCR**. Acyclovir: **crystal nephropathy**, give fluids."], "p": 107}, {"t": 6243, "title": "Reactive arthritis; shock types", "notes": ["**Cannot see, pee, climb a tree**. HLA-B27. Chlamydia (most tested), Campylobacter, Shigella.", "Hypovolemic and cardiogenic: **high SVR**. Septic: **low SVR**, high CO. Neurogenic: low HR.", "Septic shock: **fluids, then norepinephrine**."], "p": 108}, {"t": 6477, "title": "Melanoma", "notes": ["**ABCDE**. Excisional biopsy.", "Prognosis: **Breslow depth**."], "p": 110}, {"t": 6593, "title": "Diabetes drugs", "notes": ["Metformin: avoid in **renal failure** (eGFR under 30), contrast, hypoxia. **Sulfonylureas: hypoglycemia**.", "GLP-1: weight loss, pancreatitis. SGLT2: **UTIs, euglycemic DKA**. TZDs: **heart failure**."], "p": 111}, {"t": 6710, "title": "Esophageal cancer", "notes": ["**Squamous: upper third, alcohol and smoking**, most common worldwide.", "**Adenocarcinoma: lower third, Barrett, GERD**, most common in North America.", "Progressive dysphagia, weight loss. **Endoscopy with biopsy**."], "p": 112}, {"t": 6827, "title": "Clotting disorders", "notes": ["**Factor V Leiden**: most common. Activated protein C resistance.", "Needs huge heparin doses: **antithrombin III deficiency**.", "Not corrected by mixing: **lupus anticoagulant**."], "p": 113}, {"t": 6944, "title": "Zoster", "notes": ["Dermatomal vesicles. Shingles vaccine **50+**. Live vaccine contraindicated in **pregnancy, immunosuppression**.", "**Valacyclovir within 72 hours**. Post-herpetic neuralgia: gabapentin, TCA."], "p": 114}, {"t": 7060, "title": "Diabetic kidney disease", "notes": ["ESRD: **diabetes, then hypertension**. **Kimmelstiel-Wilson nodules**.", "Hypertensive emergency: lower **25% in the first hour**.", "**ACE inhibitor or ARB** + SGLT2 for proteinuria."], "p": 115}, {"t": 7177, "title": "Osteopetrosis; chronic bronchitis", "notes": ["Thick bones + CN palsies + anemia: **osteopetrosis**, osteoclast failure. Bone marrow transplant.", "Chronic bronchitis: low FEV1/FVC. **DLCO normal** (low in emphysema)."], "p": 116}, {"t": 7410, "title": "Atrial fibrillation", "notes": ["Risk: **hypertension**. Hyperthyroidism. Foci in **pulmonary veins**. Clots in **left atrial appendage**.", "Rate: beta blocker, CCB, digoxin. **CHA2DS2-VASc** for anticoagulation.", "**Valvular AFib (mitral stenosis, mechanical valve): warfarin only**."], "p": 118}, {"t": 7644, "title": "Squamous cell skin cancer; myxedema coma", "notes": ["Actinic keratosis or Marjolin: **squamous cell**, lower lip.", "Hypothermia, bradycardia, hyponatremia, hypercapnia: **myxedema coma**. **IV levothyroxine + steroids**."], "p": 120}, {"t": 7877, "title": "Sister Mary Joseph, Leser-Trelat", "notes": ["Sudden seborrheic keratoses + weight loss: **Leser-Trelat** (gastric cancer).", "**Virchow node** (left supraclavicular). Ovary mets: **Krukenberg**."], "p": 122}, {"t": 7994, "title": "Hereditary spherocytosis; septic shock", "notes": ["No central pallor + **high MCHC**: spherocytosis (spectrin, ankyrin). **Osmotic fragility, EMA binding**. Splenectomy.", "Septic shock: high CO, **low SVR, low wedge**, high mixed venous O2. Fluids, **norepinephrine**."], "p": 123}, {"t": 8227, "title": "AKI patterns and cor pulmonale", "notes": ["Pre-renal: **BUN/Cr over 20, FeNa under 1%**. Intrinsic: FeNa over 2%.", "Right heart failure: most common cause is **left heart failure**."], "p": 125}, {"t": 8460, "title": "Thyroid cancers", "notes": ["Papillary: **psammoma bodies, Orphan Annie nuclei**. Follicular: **blood spread**.", "Medullary: **calcitonin**, amyloid, **MEN 2**. Anaplastic: elderly, aggressive."], "p": 127}, {"t": 8577, "title": "Pancreatic cancer", "notes": ["Painless jaundice + **Courvoisier sign**, smoker. **CT**, CA 19-9.", "Trousseau (migratory thrombophlebitis). Celiac plexus block for pain.", "Hemolytic anemia: give **folate**."], "p": 128}, {"t": 8810, "title": "Nephritic and nephrotic patterns", "notes": ["Tram track: **MPGN**. Subepithelial humps: **PSGN**. Spike and dome: **membranous**.", "Kimmelstiel-Wilson: diabetes. **HIV: FSGS**. Normal light microscopy: minimal change."], "p": 130}, {"t": 8927, "title": "Rhabdomyolysis; mucormycosis; HS", "notes": ["Found down + peaked T + high creatinine: **rhabdo**. **Aggressive IV fluids**, treat K.", "DKA + necrotic sinusitis: **mucormycosis**. Debride + amphotericin.", "Recurrent axillary and groin abscesses: **hidradenitis suppurativa**."], "p": 131}, {"t": 9277, "title": "Hyperthyroidism", "notes": ["Best first test: **TSH**. Graves: **diffuse uptake**, TSI. Toxic adenoma: single hot. Multinodular: patchy.", "Pregnancy: high total T4 (high TBG), normal free T4."], "p": 134}, {"t": 9394, "title": "Colon polyps and sickle cell", "notes": ["**Villous adenomas** most malignant. Peutz-Jeghers: hamartomas + lip pigmentation.", "Sickle cell: **pneumococcal and meningococcal vaccines** (asplenia), Salmonella osteomyelitis, **papillary necrosis**, parvovirus aplastic crisis. Hydroxyurea."], "p": 135}, {"t": 9627, "title": "ADPKD and scleroderma", "notes": ["Worst headache + **bilateral flank masses**: ADPKD (PKD1). **Berry aneurysms**, MVP.", "CREST: **anti-centromere**. Diffuse: **anti-Scl-70**. Renal crisis: **ACE inhibitor**."], "p": 137}, {"t": 9860, "title": "PEEP barotrauma and ventilator", "notes": ["BP crash after high PEEP: **tension pneumothorax**. Needle decompression.", "High CO2: raise **rate or tidal volume**. Low O2: raise **FiO2 or PEEP**."], "p": 139}, {"t": 10094, "title": "Cellulitis vs erysipelas", "notes": ["Erysipelas: **Strep pyogenes**, upper dermis, **sharp raised border**, abrupt.", "Cellulitis: strep or staph, deeper, indistinct. Cephalexin. MRSA risk: add TMP-SMX or doxycycline."], "p": 141}]}, {"key": "d3", "id": "Fi6kIFsiWEk", "who": "Divine Intervention", "title": "Episode 31: Medicine Shelf Review, Session 3", "len": 11007, "approx": true, "label": "D3", "c": "d", "short": "Divine Ep 31", "rail": "Divine Intervention Ep 31", "pdf": "Divine%20Intervention%20Ep31.pdf", "sections": [{"t": 60, "title": "G6PD, mono, minimal change", "notes": ["G6PD: X-linked. **Sulfa, primaquine, fava beans**, infection. **Heinz bodies, bite cells**. Test after the episode.", "Rash after amoxicillin + **posterior nodes: mono**. Monospot. **No contact sports** (splenic rupture).", "Normal light microscopy, **effaced foot processes: minimal change**. Hodgkin association. Steroids."], "p": 3}, {"t": 294, "title": "Sjogren, alpha-1 antitrypsin, aortic stenosis", "notes": ["Dry eyes + mouth, baby with heart block: **Sjogren** (anti-Ro, anti-La). Lymphocytic infiltrate. **Lymphoma risk**.", "Young panacinar emphysema + liver disease: **alpha-1 antitrypsin**. PAS-positive globules.", "AS: right 2nd space to carotids. **Bicuspid valve** = early. Symptoms (angina, syncope, CHF) = **replace**."], "p": 6}, {"t": 528, "title": "Acne and CAH", "notes": ["Acne: **C acnes**. Topical retinoid or benzoyl peroxide, then topical or oral antibiotic, then **isotretinoin** (teratogen, 2 forms of contraception).", "21-hydroxylase: **salt wasting, ambiguous female genitals, high 17-OH progesterone**. 11-hydroxylase: **HTN**. 17-hydroxylase: HTN, no sex hormones."], "p": 9}, {"t": 684, "title": "Jaundice patterns and high-output failure", "notes": ["**Obstruction: high direct bilirubin, urine bilirubin, low urobilinogen, high ALP**. Hemolysis: high indirect, high urobilinogen.", "High-output failure: **anemia, AV fistula, Paget, thyrotoxicosis, beriberi**."], "p": 11}, {"t": 841, "title": "Lyme, MCTD, bronchiectasis", "notes": ["Lyme: erythema migrans. Late: **Bell palsy, AV block, arthritis**. Doxycycline, **amoxicillin in pregnancy and under 8**, IV ceftriaxone for CNS or heart block.", "MCTD: **anti-U1 RNP**.", "Bronchiectasis + renal failure: **amyloidosis**. CF, Kartagener. **High-resolution CT**."], "p": 13}, {"t": 1075, "title": "Hypertensive emergency, erythema nodosum", "notes": ["Emergency = end-organ damage. **IV labetalol, nicardipine**. Lower **25% in the first hour**.", "Erythema nodosum: **sarcoid, IBD, cocci**, strep, pregnancy."], "p": 16}, {"t": 1231, "title": "Cushing syndrome work-up", "notes": ["Screen: **overnight dexamethasone**, 24-hour urine cortisol, late-night salivary.", "Then **ACTH**: low = adrenal (CT). High = **high-dose dexamethasone**: suppresses = pituitary (MRI), no = ectopic (chest CT)."], "p": 18}, {"t": 1309, "title": "Diarrhea types and Hodgkin", "notes": ["**Osmotic gap over 125: osmotic** (lactose, laxatives). Under 50: secretory (cholera, VIPoma, carcinoid).", "Reed-Sternberg (**CD15, CD30**): Hodgkin. Nodular sclerosis most common. Lymphocyte-rich best prognosis."], "p": 19}, {"t": 1465, "title": "Rheumatic fever and membranous", "notes": ["Jones: **carditis, polyarthritis, chorea, erythema marginatum, nodules**. **Antibiotics prevent RF, not PSGN**. Mitral valve.", "Membranous: **hep B, lupus, solid tumours**, NSAIDs. Spike and dome. Anti-PLA2R."], "p": 21}, {"t": 1622, "title": "Dermatomyositis and sarcoidosis", "notes": ["Dermato (CD4, perifascicular) vs polymyositis (CD8, endomysial). **Gottron, heliotrope, shawl**. **Look for cancer** (ovary, lung). Anti-Jo-1, anti-Mi-2.", "Sarcoid: **Black woman, bilateral hilar nodes**, uveitis, erythema nodosum, **high calcium, high ACE**. Restrictive. Steroids."], "p": 23}, {"t": 1778, "title": "Heart failure", "notes": ["Systolic: low EF. Diastolic: normal EF, stiff ventricle. **BNP**, echo.", "Acute: **loop diuretic**, nitrates, BiPAP.", "Chronic HFrEF: **ACE inhibitor or ARNI, beta blocker, MRA, SGLT2**."], "p": 25}, {"t": 1856, "title": "Erythema multiforme and Cushing labs", "notes": ["Targets after **Mycoplasma or HSV**: erythema multiforme.", "Ectopic ACTH: **very high ACTH, no suppression**. Pituitary: high, suppresses. Exogenous steroids: **low ACTH, low CRH**."], "p": 26}, {"t": 2012, "title": "Cholecystitis", "notes": ["RUQ pain after fatty food, **Murphy sign**, fever. **Ultrasound**, HIDA if unclear.", "Antibiotics + **cholecystectomy**. ICU, TPN, burns: **acalculous**, percutaneous drain."], "p": 28}, {"t": 2090, "title": "Non-Hodgkin lymphomas and TB", "notes": ["Follicular: **t(14;18) BCL2**. Burkitt: **t(8;14) MYC, starry sky**, EBV. Mantle: t(11;14).", "TB: RIPE. Isoniazid: **B6**. **IGRA** not affected by BCG."], "p": 29}, {"t": 2247, "title": "Bartter, Gitelman, aortic regurgitation", "notes": ["**Bartter = loop diuretic** (high urine calcium). **Gitelman = thiazide** (low urine calcium, low Mg). Both hypokalemic alkalosis, normal BP.", "AR: blowing diastolic at LSB, **wide pulse pressure**, bounding pulses (Corrigan, de Musset, Quincke). Echo. Afterload reduction, replace."], "p": 31}, {"t": 2403, "title": "Fungal skin and PSC", "notes": ["**KOH prep**. Tinea versicolor: **spaghetti and meatballs**, Malassezia. Selenium or ketoconazole.", "**Beads on a string at ERCP + UC: PSC**. p-ANCA. Cholangiocarcinoma risk. Liver transplant."], "p": 33}, {"t": 2559, "title": "Chemotherapy side effects", "notes": ["Methotrexate: **myelosuppression, leucovorin rescue**. 5-FU: uridine rescue.", "Doxorubicin: **cardiotoxic** (dexrazoxane). Bleomycin: **pulmonary fibrosis**. Cisplatin: **nephro and ototoxic** (amifostine).", "Cyclophosphamide: **hemorrhagic cystitis (mesna)**. Vincristine: neuropathy. Vinblastine: marrow."], "p": 35}, {"t": 2637, "title": "HIV drug side effects", "notes": ["Zidovudine: **anemia**. Abacavir: **HLA-B5701**. Didanosine, stavudine: pancreatitis, neuropathy.", "Protease inhibitors: lipodystrophy, hyperglycemia. **Indinavir: stones**. Efavirenz: vivid dreams."], "p": 36}, {"t": 2715, "title": "Paget disease and giant cell arteritis", "notes": ["Hats do not fit + deafness + high-output failure: **Paget**. **Only high ALP**. Bisphosphonates. Osteosarcoma risk.", "PMR + jaw claudication + headache: **GCA**. **High-dose steroids first, then temporal artery biopsy**."], "p": 37}, {"t": 2871, "title": "Scabies and DKA", "notes": ["Finger web itch: scabies. **Permethrin**.", "DKA: insulin deficiency, **total body K low**. Fluids, insulin, potassium. **Add dextrose when glucose about 250**, continue insulin until gap closes."], "p": 39}, {"t": 3028, "title": "PBC and lead", "notes": ["Itch + RUQ pain in a middle-aged woman: **PBC** (anti-mitochondrial). **Ursodiol**, cholestyramine for itch. Transplant cures.", "Moonshiner, abdominal pain, cognition, **wrist drop: lead**. Sideroblastic anemia, **basophilic stippling**. Chelation."], "p": 41}, {"t": 3184, "title": "Shigella, EHEC, RCC", "notes": ["EHEC (O157:H7): bloody, no fever, **HUS. No antibiotics**.", "Smoker + **flank mass + hematuria + polycythemia: RCC**. Left varicocele."], "p": 43}, {"t": 3340, "title": "Carpal tunnel and PE", "notes": ["Median nerve. **Pregnancy, hypothyroid, amyloid, RA**, acromegaly. Splint, steroid injection, surgery.", "PE: Virchow triad. **ECG: sinus tachycardia** (S1Q3T3 classic). **Respiratory alkalosis**.", "Low risk: D-dimer. High risk: **CT angiogram**. Pregnancy or renal failure: **V/Q**."], "p": 45}, {"t": 3574, "title": "AFib and hypersensitivity", "notes": ["Irregularly irregular, no P waves. **Unstable: cardioversion**.", "Type I IgE, II antibody to cell, III immune complex, IV T cell."], "p": 48}, {"t": 3731, "title": "Nephrogenic DI and ALL", "notes": ["Lithium + dilute urine: **nephrogenic DI**. Thiazide, amiloride.", "TdT positive, Down syndrome, CD10/19: **B-ALL**. CD3/7 + mediastinal mass: **T-ALL**."], "p": 50}, {"t": 3887, "title": "Salmonella and PMR", "notes": ["Poultry, eggs, **turtles: Salmonella**. Typhoid: rose spots.", "Elderly with **shoulder and hip girdle pain + high ESR, normal CK**: PMR. **Low-dose prednisone**, dramatic response."], "p": 52}, {"t": 4043, "title": "Lung cancer and WPW", "notes": ["Recurrent pneumonia in the same lobe in a smoker: **obstructing tumour**. CT, bronchoscopy biopsy.", "Delta wave: WPW. **Procainamide**, avoid AV nodal blockers. Ablation."], "p": 54}, {"t": 4277, "title": "Molluscum and SIADH", "notes": ["Umbilicated papules in HIV: **molluscum**, poxvirus. ART, cryotherapy.", "Carbamazepine + low serum osm, high urine osm: **SIADH**. Fluid restriction, salt tabs, tolvaptan."], "p": 57}, {"t": 4434, "title": "Liver enzymes and hemophilia", "notes": ["**ALT more specific**. Alcohol: **AST:ALT over 2**, GGT.", "Hemophilia: X-linked, **high PTT, corrects with mixing**. Replace factor, desmopressin in mild A."], "p": 59}, {"t": 4590, "title": "Cholera, tuberous sclerosis, hemochromatosis", "notes": ["Rice-water stools: **cholera**, cAMP. **Oral rehydration**, doxycycline.", "Renal mass + cardiac rhabdomyomas + tubers: **tuberous sclerosis** (angiomyolipoma).", "Chondrocalcinosis + HFE C282Y: **pseudogout in hemochromatosis**."], "p": 61}, {"t": 4824, "title": "Histoplasma and MI arrhythmia", "notes": ["HIV + Missouri cave: **Histoplasma**. Itraconazole, amphotericin if severe.", "Death right after MI: **ventricular arrhythmia**."], "p": 64}, {"t": 5058, "title": "Pityriasis rosea and prolactinoma", "notes": ["Herald patch, then **Christmas tree**: pityriasis rosea. Reassure.", "ED, gynecomastia, **bitemporal hemianopia**: prolactinoma. **Cabergoline**, surgery if no response."], "p": 67}, {"t": 5215, "title": "Ascites and SAAG", "notes": ["**SAAG 1.1+: portal hypertension** (cirrhosis, CHF, Budd-Chiari). Under 1.1: cancer, TB, nephrotic.", "Salt restriction, **spironolactone + furosemide**, paracentesis with albumin."], "p": 69}, {"t": 5293, "title": "Tetanus, Turner, mesothelioma", "notes": ["Tetanus blocks GABA and glycine release (spasm). Botulism blocks ACh (flaccid).", "Turner: **horseshoe kidney**, coarctation.", "Shipyard + hemorrhagic effusion + pleural thickening: **mesothelioma**."], "p": 70}, {"t": 5527, "title": "ACS, HPV, thyroid on OCP", "notes": ["Unstable angina: no troponin. NSTEMI: troponin. STEMI: ST elevation.", "HPV 1 to 4 warts, **6 and 11 genital**, **16 and 18 cancer**.", "OCP or pregnancy: **high total T4, normal free T4**. Factitious: **low thyroglobulin**."], "p": 73}, {"t": 5761, "title": "SBP and TTP", "notes": ["Cirrhosis + fever + abdominal pain: **SBP**. Tap: **PMN 250+**. E coli, Klebsiella. **Ceftriaxone + albumin**.", "MAHA + fever + low platelets + renal + neuro: **TTP** (ADAMTS13). **Plasma exchange**."], "p": 76}, {"t": 5918, "title": "C diff and Alport", "notes": ["Diarrhea after clindamycin: **C diff toxin**. **Oral vancomycin or fidaxomicin**. Soap and water.", "Cannot see, pee, hear high C: **Alport** (type IV collagen)."], "p": 78}, {"t": 6074, "title": "Lung cancer and stable angina", "notes": ["Small cell: **SIADH, ACTH, Lambert-Eaton**, chemo + radiation. Squamous: **PTHrP**.", "Stable angina: ST depression on stress. **Aspirin, beta blocker, nitrate, statin**."], "p": 80}, {"t": 6230, "title": "Wilson, HIT, osteomyelitis", "notes": ["KF rings + parkinsonism + low ceruloplasmin: **Wilson**. **Penicillamine, zinc**, transplant cures.", "HIT: **prothrombotic**. PF4 antibody, serotonin release assay. Stop heparin, argatroban.", "Osteomyelitis: **S aureus**. Sickle cell: Salmonella. **Cat or dog bite: Pasteurella**. **MRI** best."], "p": 82}, {"t": 6464, "title": "GPA and nerve injuries", "notes": ["**c-ANCA**, sinus + lung + kidney: GPA. Steroids + cyclophosphamide or rituximab.", "Surgical neck or anterior dislocation: **axillary nerve**. Midshaft humerus: **radial nerve, wrist drop**."], "p": 85}, {"t": 6699, "title": "Stress tests and pseudohypoparathyroidism", "notes": ["Cannot exercise: **pharmacologic**. Baseline ECG abnormal (LBBB, digoxin, paced): **imaging stress test**.", "Low calcium + **high PTH** + short 4th and 5th metacarpals: **pseudohypoparathyroidism** (Albright)."], "p": 88}, {"t": 6933, "title": "Hepatitis viruses and ITP", "notes": ["Fecal-oral: **A and E**. E in **pregnancy** is deadly. D needs B. **C** most chronic.", "Isolated low platelets after a virus: **ITP**. Steroids, IVIG, splenectomy."], "p": 91}, {"t": 7089, "title": "Gonococcal arthritis and hyponatremia", "notes": ["Young woman + migratory arthritis + pustules: **disseminated gonorrhea**. Ceftriaxone + treat chlamydia.", "Hyponatremia: osmolality, volume, **urine sodium**."], "p": 93}, {"t": 7245, "title": "Ankylosing spondylitis and sleep apnea", "notes": ["Young man, **morning stiffness better with exercise**, bamboo spine, uveitis: AS. **NSAIDs**, TNF inhibitors.", "OSA: obesity, snoring, **polysomnography, CPAP**. Pulmonary hypertension."], "p": 95}, {"t": 7402, "title": "HOCM and hepatitis A", "notes": ["Athlete collapses: **HOCM** (autosomal dominant, myosin). **Louder with Valsalva, softer with squat**. Beta blockers, no strenuous sport.", "Traveller with flu-like illness then jaundice: **hepatitis A**. Supportive."], "p": 97}, {"t": 7558, "title": "vWD and RMSF", "notes": ["Heavy periods, **normal PT, high PTT and bleeding time**: vWD. **Desmopressin**.", "Hiking, fever, headache, rash **from wrists inward**: RMSF. **Doxycycline** at any age."], "p": 99}, {"t": 7714, "title": "Gout and Langerhans cell histiocytosis", "notes": ["First MTP: **needle-shaped negatively birefringent**. **NSAIDs, colchicine, steroids**. No aspirin. Allopurinol later.", "Young smoker, **upper lobe cysts and nodules**: pulmonary LCH. Quit smoking."], "p": 101}, {"t": 7870, "title": "Restrictive cardiomyopathy and hep B", "notes": ["Sarcoid, **amyloid**, hemochromatosis: diastolic dysfunction. Echo, biopsy.", "Needlestick from hep B, unvaccinated: **HBIG + vaccine**."], "p": 103}, {"t": 8027, "title": "DIC and babesiosis", "notes": ["Sepsis + bleeding + **high PT and PTT, low fibrinogen and platelets**: DIC. Treat cause, FFP, platelets, cryo.", "Long Island + hemoglobinuria + **Maltese cross**: **Babesia**. Atovaquone + azithromycin."], "p": 105}, {"t": 8183, "title": "Back pain causes and IPF", "notes": ["Strain: no neuro signs. Stenosis: **better leaning forward**. Cauda equina: **saddle anesthesia, retention**.", "Older non-smoker, crackles, **low DLCO, honeycombing**: IPF. Antifibrotics."], "p": 107}, {"t": 8339, "title": "Dilated cardiomyopathy and cryoglobulinemia", "notes": ["Systolic dysfunction, **S3**. Alcohol, viral, peripartum, **Chagas**, doxorubicin.", "Palpable purpura + low complement + IgM + **hep C: cryoglobulinemia**."], "p": 109}, {"t": 8495, "title": "Anaphylaxis and hypovolemia", "notes": ["Restaurant, rash, wheeze, BP 60: **IM epinephrine**.", "Pre-renal: **FeNa under 1%**, urine Na under 20. Hypovolemic hypernatremia: **NS first**, then free water."], "p": 111}, {"t": 8651, "title": "Hypercalcemia of malignancy and drug lung", "notes": ["**Bisphosphonate (zoledronic acid)**. Lytic mets: **myeloma, RCC**, breast. Blastic: prostate.", "Amiodarone: **pulmonary fibrosis**. Also bleomycin, methotrexate, nitrofurantoin."], "p": 113}, {"t": 8808, "title": "Atherosclerosis and MEN", "notes": ["Top modifiable risk: **smoking**. Homocysteine: B6, B9, B12.", "MEN1: **pituitary, parathyroid, pancreas**. MEN2A: medullary, pheo, parathyroid. 2B: medullary, pheo, neuromas, marfanoid. **Prophylactic thyroidectomy (RET)**."], "p": 115}, {"t": 8964, "title": "Hepatic encephalopathy and polycythemia vera", "notes": ["Varices: non-selective beta blocker. **Encephalopathy: lactulose + rifaximin**. TIPS worsens encephalopathy.", "PV: **JAK2**, itch after shower, **low EPO**. Phlebotomy, hydroxyurea, aspirin."], "p": 117}, {"t": 9120, "title": "Agranulocytosis and hypokalemia", "notes": ["Fever + ANC under 1500 on **methimazole or PTU**: agranulocytosis. Stop drug.", "Hypokalemia: diuretics, vomiting, **RTA 1 and 2**. HTN + alkalosis + low K: hyperaldosteronism."], "p": 119}, {"t": 9276, "title": "Disc herniation and pulmonary hypertension", "notes": ["Lifting, positive straight leg raise, **lost ankle reflex: S1**. Conservative first.", "PAH: young woman, **BMPR2**. **Right heart cath** to confirm."], "p": 121}, {"t": 9432, "title": "Statins and amoebic abscess", "notes": ["Statins: **ASCVD, LDL 190+, diabetes 40 to 75**, high risk. Myopathy.", "Liver abscess + bloody diarrhea from Africa: **Entamoeba**, **metronidazole then paromomycin**. Hydatid: albendazole + surgery."], "p": 123}, {"t": 9589, "title": "Genital ulcers and syphilis", "notes": ["**Painless indurated: syphilis**. Beefy red: granuloma inguinale. **Painful ragged: chancroid**. Painful vesicles: HSV.", "Primary, secondary, early latent: **benzathine penicillin x1**. Late: weekly x3. Neurosyphilis: IV penicillin."], "p": 125}, {"t": 9823, "title": "Hyperkalemia and nerve injuries", "notes": ["**Calcium gluconate**, insulin + glucose, albuterol, binder, dialysis. Hemolyzed sample: pseudohyperkalemia.", "Snuffbox tenderness: **scaphoid**, thumb spica + repeat x-ray or MRI."], "p": 128}, {"t": 9979, "title": "COPD and hypertension", "notes": ["Emphysema: **protease excess**. Low FEV1/FVC, high TLC. **Low DLCO in emphysema**, normal in chronic bronchitis.", "HTN: weight loss most effective. Thiazide, ACE inhibitor or ARB, CCB."], "p": 130}, {"t": 10135, "title": "Subphrenic abscess and anticoagulant reversal", "notes": ["Fever + shoulder pain + effusion after bowel surgery: **subphrenic abscess**.", "Heparin: **protamine**. Warfarin: **vitamin K + PCC**. Dabigatran: **idarucizumab**. **Warfarin for valvular AFib**."], "p": 132}, {"t": 10292, "title": "Neurocysticercosis and hypercalcemia", "notes": ["Seizures after pork in Latin America: **Taenia solium**. **Albendazole + steroids** for brain cysts.", "Hypercalcemia: **hyperparathyroidism and cancer**, thiazides. **Short QT**. **IV saline first**."], "p": 134}, {"t": 10448, "title": "Acid-base and secondary HTN", "notes": ["pH 7.25, CO2 65: **respiratory acidosis** (hypoventilation, opioids, COPD).", "Turner HTN: **coarctation**. Low K + alkalosis + high ratio: **Conn**."], "p": 136}, {"t": 10604, "title": "Multiple myeloma and malaria", "notes": ["CRAB: **calcium, renal, anemia, bone lytic lesions**. **SPEP**, free light chains, marrow over 10% plasma cells.", "Cyclic fever from Africa: **malaria**. **Thick and thin smear**."], "p": 138}, {"t": 10760, "title": "Post-thyroidectomy hypocalcemia, flail chest, salicylates", "notes": ["Long QT + Trousseau after thyroidectomy: **hypocalcemia**. IV calcium.", "Rib fractures + RR 8 + high CO2: **intubate**. Do not strap ribs.", "Aspirin overdose: **respiratory alkalosis then gap acidosis**."], "p": 140}]}, {"key": "d4", "id": "t7tof3gh_VU", "who": "Divine Intervention", "title": "Episode 32: Medicine Shelf Review, Session 4", "len": 8951, "approx": true, "label": "D4", "c": "d", "short": "Divine Ep 32", "rail": "Divine Intervention Ep 32", "pdf": "Divine%20Intervention%20Ep32.pdf", "sections": [{"t": 60, "title": "Unstable angina and fat-soluble vitamins", "notes": ["UA: **no ST elevation, no troponin**. NSTEMI: troponin. No fibrinolytics.", "Fat malabsorption: **A (night blindness), D, E (ataxia), K (bleeding)**. Warfarin reversal: vitamin K + PCC."], "p": 3}, {"t": 335, "title": "Giardia, phosphate, shoulder", "notes": ["Camping + foul fatty diarrhea: **Giardia**. Stool antigen. **Metronidazole or tinidazole**. IgA deficiency.", "Chronic high phosphate: **CKD**. Binders. Tumour lysis: **high K, phosphate, uric acid, low calcium**.", "Anterior dislocation: axillary nerve. **Posterior: seizure or electric shock**."], "p": 5}, {"t": 747, "title": "Cystic fibrosis and Prinzmetal", "notes": ["CF: autosomal recessive, **delta F508**. **Sweat chloride**. S aureus young, Pseudomonas older.", "Night chest pain in young female smoker with migraines: **Prinzmetal**. **CCB**, nitrates. Avoid non-selective beta blockers."], "p": 8}, {"t": 1022, "title": "Pinworm and AML", "notes": ["Anal itch in a child: **Enterobius**, tape test, albendazole.", "Over 20% blasts, MPO, **Auer rods: AML**. **M3 (t15;17): ATRA**, DIC."], "p": 10}, {"t": 1297, "title": "Amebiasis and A-a gradient", "notes": ["Bloody diarrhea + liver abscess: **Entamoeba**. **Metronidazole + paromomycin**. Clonorchis: cholangiocarcinoma.", "**Normal A-a: hypoventilation, altitude**. High A-a: V/Q mismatch, shunt, diffusion."], "p": 12}, {"t": 1572, "title": "MI localization and CLL", "notes": ["II, III, aVF inferior (RCA). V1 to V4 anterior (LAD). I, aVL, V5 to V6 lateral (LCx). **RV infarct: no nitrates**.", "Reinfarction: **CK-MB** (troponin stays up).", "Elderly, **lymphocytes 100K, smudge cells: CLL**. Warm AIHA."], "p": 14}, {"t": 1847, "title": "Vibrio and magnesium toxicity", "notes": ["Raw oysters: **Vibrio vulnificus**, deadly in **liver disease**. Doxycycline + ceftriaxone.", "Falling reflexes on magnesium: **toxicity**. Stop infusion, **calcium gluconate**."], "p": 16}, {"t": 2122, "title": "Pulmonary edema and reperfusion", "notes": ["Cardiogenic: high wedge. Treat **furosemide, nitrates**, oxygen, BiPAP.", "**PCI within 90 minutes** if available. tPA if no PCI within 120 minutes. **Left main or 3-vessel: CABG**."], "p": 18}, {"t": 2397, "title": "Lactose intolerance and hairy cell", "notes": ["Asian, bloating after cheese: lactase deficiency. **Hydrogen breath test**.", "**Dry tap, TRAP positive, hairy projections**: hairy cell leukemia. **Cladribine**.", "Fried rice: **B cereus**."], "p": 20}, {"t": 2810, "title": "PAN and pneumothorax", "notes": ["Hep B + mononeuritis + **mesenteric ischemia**, ANCA negative: **PAN**. Steroids, cyclophosphamide.", "Primary spontaneous: **tall thin young male smoker**. Tension: **tracheal deviation, hypotension, needle**."], "p": 23}, {"t": 3085, "title": "Emphysema and pneumoconioses", "notes": ["Centriacinar: **smoking**, upper lobes. Panacinar: **alpha-1 antitrypsin**, lower lobes. Low DLCO.", "Asbestosis: lower lobe, **ferruginous bodies**, plaques. **Bronchogenic cancer more common than mesothelioma**."], "p": 25}, {"t": 3360, "title": "Blastomycosis and empiric antibiotics", "notes": ["Indiana + **broad-based budding yeast**: Blastomyces. Itraconazole.", "Prosthetic valve endocarditis: **S epidermidis**. Hospital diarrhea: C diff.", "Gonorrhea: **ceftriaxone + doxycycline**. Pyelonephritis: ciprofloxacin or ceftriaxone."], "p": 27}, {"t": 3772, "title": "HIV complications and CML", "notes": ["Single ring lesion: **CNS lymphoma (EBV)**. Multiple: toxo.", "CML: **BCR-ABL t(9;22)**, high basophils, **imatinib**."], "p": 30}, {"t": 4047, "title": "Neutropenic fever, eosinophilia, HIV pneumonia", "notes": ["Neutropenic fever: **blood cultures then cefepime or piperacillin-tazobactam**.", "Eosinophilia: **NAACP** (neoplasm, allergy, Addison, collagen vascular, parasites).", "HIV, CD4 150, **lobar pneumonia: S pneumoniae**."], "p": 32}, {"t": 4460, "title": "HIV opportunistic infections", "notes": ["Retinitis: **CMV**. Esophagitis: Candida. Meningitis: **Cryptococcus**.", "Bacillary angiomatosis: **Bartonella**. PML: **JC virus**."], "p": 35}, {"t": 4598, "title": "Metabolic acidosis and alkalosis", "notes": ["Gap: MUDPILES. Non-gap: diarrhea, RTA. **Urine anion gap negative = diarrhea**.", "Alkalosis: **vomiting, diuretics**, hyperaldosteronism."], "p": 36}, {"t": 4873, "title": "Bladder cancer, dialysis, pyelonephritis", "notes": ["Smoker, schistosomiasis, **cyclophosphamide**: bladder cancer. **Cystoscopy**.", "Dialysis AEIOU. Long-term dialysis: **beta-2 microglobulin amyloid**.", "Fever + **CVA tenderness**: pyelonephritis. **WBC casts**. Ciprofloxacin or ceftriaxone."], "p": 38}, {"t": 5285, "title": "Diuretics and FSGS", "notes": ["Loop: ototoxic, **hypokalemia**. Thiazide: **hyperglycemia, hypercalcemia, gout**. Spironolactone: **gynecomastia, hyperkalemia**.", "FSGS: **Black patients, HIV, heroin, obesity**. Collapsing in HIV. Steroids."], "p": 41}, {"t": 5560, "title": "RPGN and tamponade", "notes": ["**Goodpasture: linear IgG**, hemoptysis. PSGN: lumpy bumpy. IgA: mesangial. HSP: purpura.", "Tamponade: **Beck triad**, pulsus paradoxus. **Pericardiocentesis**."], "p": 43}, {"t": 5973, "title": "SVT, WPW, QT", "notes": ["AVNRT: **vagal, adenosine**, unstable = cardioversion. WPW: procainamide.", "Long QT: **macrolides, antipsychotics, ondansetron, low K, Mg, Ca**. Torsades: **IV magnesium**."], "p": 46}, {"t": 6660, "title": "Hemodynamic arrows and vascular lesions", "notes": ["Milrinone: higher contractility, lower SVR. Norepinephrine: higher SVR. Hydralazine: lower afterload.", "Knife wound + **pulsatile mass + high-output state: AV fistula**.", "Young Asian woman, **arm BP difference, pulseless**: **Takayasu**. Steroids."], "p": 51}, {"t": 7073, "title": "Constrictive pericarditis and post-MI", "notes": ["**Pericardial knock, Kussmaul sign**: constrictive. Calcified pericardium.", "After MI: arrhythmia (first day), **free wall rupture (5 to 14 days)**, septal, papillary, Dressler (weeks)."], "p": 54}, {"t": 7348, "title": "Colon screening and GERD drugs", "notes": ["Screening: **50 (45) every 10 years**. First-degree relative at 52: **start at 40 or 10 years earlier**.", "Many polyps at 22: **FAP**. Polyps + osteomas: Gardner.", "PPIs: **C diff, fractures, low Mg, B12**."], "p": 56}, {"t": 7623, "title": "Hepatic adenoma, Whipple, Zenker", "notes": ["Long-term OCP + liver mass: **hepatic adenoma**. Stop OCP, resect if large.", "Arthralgia + diarrhea + **PAS-positive macrophages: Whipple** (Tropheryma). Ceftriaxone then TMP-SMX.", "Halitosis + dysphagia + neck mass: **Zenker**. **Barium swallow**, no endoscopy first."], "p": 58}, {"t": 8035, "title": "Glucagonoma, gastroparesis, Ogilvie", "notes": ["Diabetes + **necrolytic migratory erythema**: glucagonoma.", "Gastroparesis: **metoclopramide, erythromycin**.", "Septic patient, massive colonic dilation, no obstruction: **Ogilvie**. Neostigmine, decompression."], "p": 61}, {"t": 8310, "title": "Hepatorenal syndrome and diarrhea bugs", "notes": ["ESLD + oliguria + **urine Na under 10**, no response to fluids: **hepatorenal**. Albumin + vasoconstrictors, transplant.", "Cruise ship: **norovirus**. Potato salad: **S aureus**. Daycare: Shigella, rotavirus."], "p": 63}, {"t": 8585, "title": "Alcohol liver disease and MEN1", "notes": ["**AST:ALT over 2**, high GGT. Hepatotoxins: valproate, statins, TB drugs, acetaminophen, amiodarone.", "MEN1 + jejunal ulcers: **Zollinger-Ellison**. **Secretin stimulation test**. High-dose PPI, resect."], "p": 65}, {"t": 8861, "title": "Autoimmune hepatitis and cirrhosis", "notes": ["Type 1: **anti-smooth muscle, ANA**. Type 2: anti-LKM1.", "Cirrhosis: varices, ascites, SBP, **encephalopathy (lactulose)**, HCC screening (ultrasound)."], "p": 67}]}];
